        #region 資料庫Update相關
        public static void WriteDBWorkLog(string FileName, string context)
        {
            string FixFileName = FileName + ".txt";

            try
            {
                FileStream fs = new FileStream(FixFileName, FileMode.Append);

                StreamWriter sr = new StreamWriter(fs);

                sr.WriteLine(context);

                sr.Flush();

                sr.Close();

                fs.Close();
            }
            catch (Exception e)
            {
                MyConsole.WriteLine("The file could not be read:");
                MyConsole.WriteLine(e.Message);
                MyConsole.WriteLine(e.StackTrace);
            }
        }

        static void WriteOperTionToWorkLog(OperTionDBBox Temp)
        {
            if (Temp == null) return;

            string context = "";

            switch (Temp.Type)
            {
                case OpertionCode.insert:
                    {
                        //取更新的所有鍵
                        string field1 = "";
                        string field2 = "";

                        foreach (string key in Temp.Data.Keys)
                        {
                            field1 += "," + key;
                            field2 += "," + Temp.Data[key];
                        }

                        context = "INSERT INTO " + Temp.TableName + " (" + field1.Trim(',') + ") VALUE (" + field2.Trim(',') + ")";

                        WriteDBWorkLog(Temp.TableName, context);
                    }
                    break;
                case OpertionCode.update1:
                    {
                        string filed1 = "";

                        foreach (string key in Temp.Data.Keys)
                        {
                            filed1 += "," + key + "=" + Temp.Data[key];
                        }

                        context = "UPDATE " + Temp.TableName + " SET " + filed1.Trim(',') + " WHERE " + Temp.Col + "=" + Temp.Value;

                        WriteDBWorkLog(Temp.TableName, context);
                    }
                    break;
                case OpertionCode.update2:
                    {
                        string filed1 = "";

                        foreach (string key in Temp.Data.Keys)
                        {
                            filed1 += "," + key + "=" + Temp.Data[key];
                        }

                        context = "UPDATE " + Temp.TableName + " SET " + filed1.Trim(',') + " WHERE " + Temp.Where;

                        WriteDBWorkLog(Temp.TableName, context);
                    }
                    break;
                case OpertionCode.delete:
                    {
                        context = "DELETE FROM " + Temp.TableName + " WHERE " + Temp.Where;

                        WriteDBWorkLog(Temp.TableName, context);
                    }
                    break;
                case OpertionCode.insertUpdate:
                    {
                        string field1 = "";
                        string field2 = "";
                        string field3 = "";

                        foreach (string key in Temp.Data.Keys)
                        {
                            field1 += "," + key;
                            field2 += "," + Temp.Data[key];
                            field3 += ", " + key + " = VALUES(" + key + ")";
                        }

                        context = "INSERT INTO " + Temp.TableName + " (" + field1.Trim(',') + ") VALUES (" + field2.Trim(',') + ") ON DUPLICATE KEY UPDATE " + field3.Trim(',');

                        WriteDBWorkLog(Temp.TableName, context);
                    }
                    break;
                case OpertionCode.runsql:
                    {
                        context = Temp.Where;
                        WriteDBWorkLog(Temp.TableName, context);
                    }
                    break;
                //case OpertionCode.replace: //未使用
                //case OpertionCode.specProc: //未使用
            }
        }

        static void ShowDBBoxDebugMsg(OperTionDBBox Temp, int result)
        {
            string log = "result:" + result.ToString();

            Console.WriteLine(log);

            string cmd = "";

            if (Temp.Data != null)
            {
                foreach (KeyValuePair<string, string> item in Temp.Data)
                {
                    cmd = cmd + item.Key + "_" + item.Value + ",";
                }
            }

            string tablename = "";
            string col = "";
            string value = "";
            string where = "";
            string order = "";

            if (Temp.TableName != null)
            {
                tablename = Temp.TableName;
            }

            if (Temp.Col != null)
            {
                col = Temp.Col;
            }

            if (Temp.Value != null)
            {
                value = Temp.Value;
            }

            if (Temp.Where != null)
            {
                where = Temp.Where;
            }

            if (Temp.Order != null)
            {
                order = Temp.Order;
            }

            log = "Type:" + Enum.GetName(typeof(OpertionCode), Temp.Type) + " TableName:" + tablename;
            log = log + " Data:" + cmd + " Col:" + col + " Value:" + value + " Where:" + where +
                " Order:" + order + " MachineUID:" + Temp.MachineUID;

            Console.WriteLine(log);
        }

        private static void OperTionDBCommend(object state)
        {
            MysqlTest test = new MysqlTest();

            OperTionDBBox Temp = null;

            int ErrorCnt = 0;

            while (true)
            {
                if (Temp == null)
                {
                    lock (opertionDBBoxs)
                    {
                        if (opertionDBBoxs.Count > 0)
                        {
                            Temp = opertionDBBoxs[0];
                            opertionDBBoxs.RemoveAt(0);
                            //Console.WriteLine("opertionDBBoxs-- :{0}", opertionDBBoxs.Count, Console.ForegroundColor = ConsoleColor.Cyan);
                        }
                    }
                }


                if (MySqlErrorFg == false)
                {
                    int result = 0;

                    if (Temp != null)
                    {
                        if (GeneralCommandFg == true)
                        {
                            lock (DBCache.GeneralList)
                            {
                                if (!DBCache.GeneralList.ContainsKey(Temp.TableName))
                                {
                                    DBCache.GeneralList.Add(Temp.TableName, 1);
                                }
                                else
                                {
                                    DBCache.GeneralList[Temp.TableName] += 1;
                                }
                            }
                        }

                        //if (Temp.TableName == "Usertable")
                        //{
                        //
                        //}

                        try
                        {
                            switch (Temp.Type)
                            {
                                case OpertionCode.insert:
                                    {
                                        result = test.insert(Temp.TableName, Temp.Data);
                                    }
                                    break;
                                case OpertionCode.select:
                                    {

                                    }
                                    break;
                                case OpertionCode.update1:
                                    {
                                        //if (Temp.TableName == "JPCounttable")
                                        //{
                                        //    result = test.update(Temp.TableName, Temp.Data, Temp.Col, Temp.Value);
                                        //}
                                        //else
                                        {
                                            result = test.update(Temp.TableName, Temp.Data, Temp.Col, Temp.Value);
                                        }
                                    }
                                    break;
                                case OpertionCode.update2:
                                    {
                                        result = test.update(Temp.TableName, Temp.Data, Temp.Where);
                                    }
                                    break;
                                case OpertionCode.replace:
                                    {

                                    }
                                    break;
                                case OpertionCode.get:
                                    {

                                    }
                                    break;
                                case OpertionCode.delete:
                                    {
                                        result = test.delete(Temp.TableName, Temp.Where);
                                    }
                                    break;
                                case OpertionCode.specProc:
                                    {
                                        //Console.WriteLine("更新日帳");
                                        //result = DBCache.UpdateAccountDetailData(Temp.GameServerCode, Temp.MachineUID, Temp.Value, Temp.Data);
                                    }
                                    break;
                                case OpertionCode.insertUpdate:
                                    {
                                        result = test.insertUpdate(Temp.TableName, Temp.Data);
                                    }
                                    break;
                                case OpertionCode.runsql:
                                    {
                                        result = test.runsql(Temp.TableName, Temp.Where);
                                    }
                                    break;
                            }

                            if (result < 0)
                            {
                                ShowDBBoxDebugMsg(Temp, result);

                                string log = Enum.GetName(typeof(System.Data.ConnectionState), test.GetStatus());

                                MyConsole.WriteLine(log);

                                ErrorCnt += 1;

                                if (ErrorCnt >= ErrorLimit)
                                {
                                    MySqlErrorFg = true;

                                    WriteOperTionToWorkLog(Temp);
                                }
                                else
                                {
                                    continue;
                                }
                            }
                            else
                            {
                                ErrorCnt = 0;
                            }
                        }
                        catch (Exception e)
                        {
                            string log = "Exception:" + e.Message;

                            Console.WriteLine(log);

                            test.CloseCoon();

                            test = new MysqlTest();

                            ShowDBBoxDebugMsg(Temp, result);

                            log = Enum.GetName(typeof(System.Data.ConnectionState), test.GetStatus());

                            MyConsole.WriteLine(log);

                            ErrorCnt += 1;

                            if (ErrorCnt >= ErrorLimit)
                            {
                                MySqlErrorFg = true;

                                WriteOperTionToWorkLog(Temp);
                            }
                            else
                            {
                                continue;
                            }
                        }
                    }
                }
                else
                {
                    WriteOperTionToWorkLog(Temp);
                }

                Temp = null;

                Thread.Sleep(1);
            }
        }

        private static void UserGameDataDBCommend(object state)
        {
            MysqlTest test = new MysqlTest();

