        private static void UserSessionAccountDBCommend(object state)
        {
            MysqlTest test = new MysqlTest();

            List<Dictionary<string, string>> Temp = new List<Dictionary<string, string>>();

            List<OperTionDBBox> UpdataTemp = new List<OperTionDBBox>();

            int ErrorCnt = 0;

            while (true)
            {
                if (UpdataTemp.Count == 0)
                {
                    UpdataTemp = DBCache.GetUserSessionAccountDBUpdateData();
                }

                int result = 0;

                if (UpdataTemp.Count > 0)
                {
                    if (MySqlErrorFg == false)
                    {
                        try
                        {
                            result = test.batchupdata(UpdataTemp);

                            if (result < 0)
                            {
                                test.CloseCoon();

                                test = new MysqlTest();

                                result = test.batchupdata(UpdataTemp);

                                if (result < 0)
                                {
                                    ErrorCnt += 1;

                                    if (ErrorCnt >= ErrorLimit)
                                    {
                                        MySqlErrorFg = true;

                                        WriteDBWorkLog(UpdataTemp[0].TableName, test.sqlcontext);
                                    }
                                    else
                                    {
                                        continue;
                                    }
                                }
                                else
                                {
                                    ErrorCnt = 0;
                                }
                            }
                            else
                            {
                                ErrorCnt = 0;
                            }
                        }
                        catch (Exception e)
                        {
                            string log = "Exception:" + e.Message;

                            Console.WriteLine(log);

                            test.CloseCoon();

                            test = new MysqlTest();

                            log = "result:" + result.ToString();

                            Console.WriteLine(log);

                            ErrorCnt += 1;

                            if (ErrorCnt >= ErrorLimit)
                            {
                                MySqlErrorFg = true;

                                WriteDBWorkLog(UpdataTemp[0].TableName, test.sqlcontext);
                            }
                            else
                            {
                                continue;
                            }
                        }
                    }
                    else
                    {
                        string order = "";

                        Dictionary<string, Dictionary<string, string>> value = new Dictionary<string, Dictionary<string, string>>();

                        string TableName = UpdataTemp[0].TableName;
                        string Col = UpdataTemp[0].Col;

                        string filed1 = "UPDATE " + TableName + " SET ";
                        string filed2 = "";
                        string filed3 = " WHERE " + Col + " IN (";

                        int b = 0;
                        int c = 0;

                        foreach (OperTionDBBox t in UpdataTemp)
                        {
                            foreach (KeyValuePair<string, string> i in t.Data)
                            {
                                if (value.ContainsKey(i.Key))
                                {
                                    if (value[i.Key].ContainsKey(t.Value))
                                    {
                                        value[i.Key][t.Value] = i.Value;
                                    }
                                    else
                                    {
                                        value[i.Key].Add(t.Value, i.Value);
                                    }
                                }
                                else
                                {
                                    Dictionary<string, string> pairs = new Dictionary<string, string>();
                                    pairs.Add(t.Value, i.Value);
                                    value.Add(i.Key, pairs);
                                }
                            }
                        }

                        foreach (KeyValuePair<string, Dictionary<string, string>> v in value)
                        {
                            if (c != 0)
                            {
                                filed2 += ",";
                            }

                            filed2 += v.Key + " = CASE " + Col + " ";

                            foreach (KeyValuePair<string, string> n in v.Value)
                            {
                                filed2 += "WHEN " + n.Key + " THEN " + n.Value + " ";

                                if (c == 0)
                                {
                                    if (b != 0)
                                    {
                                        filed3 += ",";
                                    }

                                    filed3 += n.Key;

                                    b = 1;
                                }
                            }

                            filed2 += "END";

                            c = 1;
                        }

                        filed3 += ")";

                        order = filed1 + filed2 + filed3;

                        WriteDBWorkLog(UpdataTemp[0].TableName, order);
                    }
                }

                UpdataTemp.Clear();

                Thread.Sleep(3000);
            }
        }

