        static void Listener_ReceiveClientData(AsyncUserToken token, byte[] buffer)
        {

            MessageData NewMessage = new MessageData(token, buffer);

            lock (messageDatas)
            {
                messageDatas.Add(NewMessage);
            }

            //Console.WriteLine("執行完畢{0}:[{1}]", RicevieData.operationCode, DateTime.Now);
        }

        static void SendResponse(AsyncUserToken token, ErrorCode code)
        {
            //string txt = "";
            //txt = "WebSer:" + m_ListenWebServerSocket.GetCheckIPList()[4];
            //MyConsole.WriteLine(txt);
            //txt = "APISer:" + m_ListenWebAPIServerSocket.GetCheckIPList()[6];
            //MyConsole.WriteLine(txt);
            //txt = "token:" + token.Socket.LocalEndPoint.ToString();
            //MyConsole.WriteLine(txt);

            if (m_ListenWebServerSocket.AsyncWebServers.ConnectedWeb != null)
            {
                if (m_ListenWebServerSocket.GetCheckIPList()[4] == token.Socket.LocalEndPoint.ToString())
                {
                    m_ListenWebServerSocket.SendMessage(token, Message.SerializrToStream(Message.Pack(code)));
                }
            }

            if (m_ListenWebAPIServerSocket.AsyncWebAPIServers.ConnectedWeb != null)
            {
                if (m_ListenWebAPIServerSocket.GetCheckIPList()[6] == token.Socket.LocalEndPoint.ToString())
                {
                    m_ListenWebAPIServerSocket.SendMessage(token, Message.SerializrToStream(Message.Pack(code)));
                }
            }
        }

        private static void HandleMessage(object state)
        {
            while (true)
            {
                MessageData Temp = null;

                lock (messageDatas)
                {
                    if (messageDatas.Count > 0)
                    {
                        Temp = messageDatas[0];
                        messageDatas.RemoveAt(0);
                        //Console.WriteLine("messageDatas-- :{0}", messageDatas.Count, Console.ForegroundColor = ConsoleColor.Cyan);
                    }
                }

                if (Temp != null)
                {
                    try
                    {
                        object messageObject = Message.DeserializeFromStream(Temp.buffer);

                        if (messageObject != null)
                        {
                            Type messageType = messageObject.GetType();

                            switch (messageType.Name)
                            {
                                case "PhoneNumberData":
                                    {
                                        PhoneNumberData RicevieData = messageObject as PhoneNumberData;

                                        AsyncUserToken token = Temp.token;

                                        if (RicevieData != null)
                                        {
                                            switch (RicevieData.Type)
                                            {

                                                #region EditPhoneNumber
                                                case "EditPhoneNumber":
                                                    {
                                                        if (DBCache.EditUserPhone(RicevieData.UserUID, RicevieData.PhoneNumber))
                                                        {
                                                            RicevieData.Status = "0";
                                                        }
                                                        else
                                                        {
                                                            RicevieData.Status = "9000";
                                                        }

                                                        m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(RicevieData));
                                                    }
                                                    break;
                                                #endregion

                                                #region GetPhoneNumber
                                                case "GetPhoneNumber":
                                                    {
                                                        try
                                                        {
                                                            string PhoneNumber = DBCache.GetUserPhoneNumber(RicevieData.UserUID);

                                                            if (PhoneNumber == "Error")
                                                            {
                                                                RicevieData.Status = "9000";
                                                            }
                                                            else
                                                            {
                                                                RicevieData.Status = "0";
                                                                RicevieData.PhoneNumber = PhoneNumber;
                                                            }
                                                        }
                                                        catch (Exception ex)
                                                        {
                                                            RicevieData.Status = "9000";
                                                        }

                                                        m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(RicevieData));
                                                    }
                                                    break;
                                                    #endregion
                                            }
                                        }
                                    }
                                    break;
                                case "UserRegisteredData":
                                    {
                                        UserRegisteredData RicevieData = (UserRegisteredData)messageObject;

                                        AsyncUserToken token = Temp.token;

                                        if (RicevieData != null)
                                        {
                                            switch (RicevieData.operationCode)
                                            {
                                                #region Registered
                                                case OperationCode.Registered:
                                                    {
                                                        lock (AddPlayerlock)
                                                        {
                                                            RicevieData.UserAccount = RicevieData.UserAccount.Replace(" ", "");
                                                            RicevieData.Password = RicevieData.Password.Replace(" ", "");
                                                            RicevieData.CPassword = RicevieData.CPassword.Replace(" ", "");
                                                            RicevieData.ManagerAccount = RicevieData.ManagerAccount.Replace(" ", "");

                                                            //string UserIntroducer = RicevieData.IntroducerAccount.Replace(" ", "");

                                                            string TempLength = RicevieData.UserAccount;

                                                            bool RegisteredInfoFg = true;

                                                            if (RicevieData.ManagerAccount == "") //&& UserIntroducer == "")
                                                            {
                                                                m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(Message.PackUserRegisteredData(OperationCode.Registered, "", "", "", "", "9013", RicevieData.RemoteEndPoint)));

                                                                RegisteredInfoFg = false;
                                                            }

                                                            if (RegisteredInfoFg == false) continue;

                                                            if (!Regex.IsMatch(RicevieData.UserAccount, @"^\w+$"))
                                                            {
                                                                m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(Message.PackUserRegisteredData(OperationCode.Registered, "", "", "", "", "9010", RicevieData.RemoteEndPoint)));

                                                                RegisteredInfoFg = false;
                                                            }

                                                            if (RegisteredInfoFg == false) continue;

                                                            for (int i = 0; i < RicevieData.Password.Length; i++)
                                                            {
                                                                if (!Regex.IsMatch(RicevieData.Password.ToCharArray()[i].ToString(), @"^\w+$"))
                                                                {
                                                                    m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(Message.PackUserRegisteredData(OperationCode.Registered, "", "", "", "", "9011", RicevieData.RemoteEndPoint)));

                                                                    RegisteredInfoFg = false;

                                                                    break;
                                                                }
                                                            }

                                                            if (RegisteredInfoFg == false) continue;

                                                            if (RicevieData.UserAccount == "")
                                                            { m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(Message.PackUserRegisteredData(OperationCode.Registered, "", "", "", "", "9004", RicevieData.RemoteEndPoint))); RegisteredInfoFg = false; }
                                                            if (RegisteredInfoFg == false) continue;
                                                            if (TempLength.Count() < 6)
                                                            { m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(Message.PackUserRegisteredData(OperationCode.Registered, "", "", "", "", "9005", RicevieData.RemoteEndPoint))); RegisteredInfoFg = false; }
                                                            if (RegisteredInfoFg == false) continue;
                                                            if (TempLength.Count() > 24)
                                                            { m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(Message.PackUserRegisteredData(OperationCode.Registered, "", "", "", "", "9006", RicevieData.RemoteEndPoint))); RegisteredInfoFg = false; }
                                                            if (RegisteredInfoFg == false) continue;

                                                            if (RicevieData.Password == "")
                                                            { m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(Message.PackUserRegisteredData(OperationCode.Registered, "", "", "", "", "9007", RicevieData.RemoteEndPoint))); RegisteredInfoFg = false; }
                                                            if (RegisteredInfoFg == false) continue;
                                                            if (RicevieData.Password.Count() < 6)
                                                            { m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(Message.PackUserRegisteredData(OperationCode.Registered, "", "", "", "", "9008", RicevieData.RemoteEndPoint))); RegisteredInfoFg = false; }
                                                            if (RegisteredInfoFg == false) continue;
                                                            if (RicevieData.Password.Count() > 12)
                                                            { m_ListenLoginSocket.SendMessage(token, Message.SerializrToStream(Message.PackUserRegisteredData(OperationCode.Registered, "", "", "", "", "9009", RicevieData.RemoteEndPoint))); RegisteredInfoFg = false; }
                                                            if (RegisteredInfoFg == false) continue;

                                                            if (RicevieData.Password == RicevieData.CPassword)
                                                            {
                                                                //驗證玩家帳號是否重複
                                                                if (DBCache.VerificationUserID(RicevieData.UserAccount))
                                                                {
                                                                    //查詢管理者有沒有錢的上限
                                                                    //MysqlAcess myAcess = MysqlAcess.GetInstance();

                                                                    List<Dictionary<string, string>> Manegerlisert = new List<Dictionary<string, string>>();
                                                                    Manegerlisert = myAcess.select("AspNetUsers", "*", string.Format("UserName = '{0}'", RicevieData.ManagerAccount));

                                                                    if (Manegerlisert.Count > 0)
                                                                    {

                                                                        var Entitylisert = myAcess.select("Entity", "*", string.Format("id = {0}", Manegerlisert[0]["ParentId"]));

                                                                        if (Entitylisert.Count > 0 && Entitylisert[0]["IsInternetCafe"] == "True")
                                                                        {
                                                                            //新增會員資料
                                                                            int newUserUID = DBCache.InsertUserData(Int32.Parse(Entitylisert[0]["id"]),
                                                                                               Manegerlisert[0]["Id"],
                                                                                               RicevieData.UserAccount,
                                                                                               2,
                                                                                               RicevieData.Password,
                                                                                               0,
                                                                                               Convert.ToBoolean(Entitylisert[0]["CalFg"]),
                                                                                               RicevieData.PhoneNumber);

                                                                            //更新代理商資料
                                                                            var EntityData = new Dictionary<string, string>();
                                                                            EntityData.Add("IsOperate", "1");
                                                                            OperTionDBBox TempOperTionDBBox2 = new OperTionDBBox(OpertionCode.update1, "Entity", EntityData, "id", string.Format("'{0}'", Entitylisert[0]["id"]));
                                                                            lock (Program.opertionDBBoxs)
                                                                            {
