                                                        List<UserTransaction> TempUserTransaction = new List<UserTransaction>();
                                                        var datalist = myAcess.select("MangerToUserTradeRecord", "*", string.Format("UserUID = {0} && IP != 'Rebate'", RicevieData.userData.memberUniquelID.ToString()), "Buildtime DESC");

