                                                                string TempStartTime = Convert.ToDateTime(RicevieData.useraccountdata.StartTime).ToString("yyyy/MM/dd HH:mm:ss");
                                                                string TempEndTime = Convert.ToDateTime(RicevieData.useraccountdata.EndTime).ToString("yyyy/MM/dd HH:mm:ss");

                                                                DateTime DBTime = Convert.ToDateTime(TempDBTime.Remove(11, TempDBTime.Length - 11));
                                                                DateTime StartTime = Convert.ToDateTime(RicevieData.useraccountdata.StartTime);
                                                                DateTime EndTime = Convert.ToDateTime(RicevieData.useraccountdata.EndTime);

                                                                //Console.WriteLine("DBTime:{0}", DBTime);
                                                                //Console.WriteLine("StartTime:{0}", StartTime);
                                                                //Console.WriteLine("EndTime:{0}", EndTime);

                                                                int DBTimeStartTime = DateTime.Compare(DBTime, StartTime);
                                                                int DBTimeEndTime = DateTime.Compare(DBTime, EndTime);

                                                                if (UserUID == RicevieData.userData.memberUniquelID && DBTimeStartTime >= 0 && DBTimeEndTime <= 0)
                                                                {
                                                                    UserTransaction tempdata = new UserTransaction();
                                                                    tempdata.TransactionNo = temp["TransactionID"];
                                                                    tempdata.TransactionTime = Convert.ToDateTime(temp["Buildtime"]).ToString("yyyy/MM/dd HH:mm:ss");
                                                                    tempdata.TransactionType = temp["OperationType"];
                                                                    tempdata.PaymentType = "Instant Cash";
