                                                                    if (ServerStatus == ServerWorkEnum.Work)
                                                                    {
                                                                        lock (AddPlayerlock)
                                                                        {
                                                                            bool IsBroken = false;
                                                                            bool IsOverUnit = false;
                                                                            bool IsOverPlayerLimit = false;
                                                                            //查詢管理者有沒有錢的上限
                                                                            //MysqlAcess myAcess = MysqlAcess.GetInstance();
                                                                            var Permissiondatalist = myAcess.select("permissiontable", "BalanceUnlimited", string.Format("PermissionUID = '{0}'", RicevieData.webInfo.Deals[0].OperatorId));
                                                                            decimal managerBalance = GetAspNetUsersBalance(RicevieData.webInfo.Deals[0].OperatorId);

                                                                            if (Permissiondatalist.Count > 0)
                                                                            {
                                                                                //如果有上限
