                                                                                    for (int i = 0; i < RicevieData.webInfo.Deals.Count; i++)
                                                                                    {
                                                                                        tempBalacne -= Math.Round((decimal)RicevieData.webInfo.Deals[i].Amount, AccuracyDigit);

                                                                                        if (tempBalacne < 0)
                                                                                        {
                                                                                            IsBroken = true;
                                                                                        }
                                                                                    }
                                                                                }

                                                                                CountrySettingData countrySettingData = DBCache.GetCountryExtraBonusString();

                                                                                double countryManagerBalanceLimit = 0;
                                                                                double countryManagerDepositUnit = 0;
                                                                                DBCache.GetManagerBalanceLimit(ref countryManagerBalanceLimit, ref countryManagerDepositUnit);

                                                                                //看看下線管理者被 開洗後 錢會不會超出限制
                                                                                for (int i = 0; i < RicevieData.webInfo.Deals.Count; i++)
                                                                                {
