                                                                                            Manegerdata.Add("RecipientId", "'" + RicevieData.webInfo.Deals[i].UserUID + "'");
                                                                                        }
                                                                                        else
                                                                                        {
                                                                                            Manegerdata.Add("OperationType", "'Withdrawal'");
                                                                                            Manegerdata.Add("PayerId", "'" + RicevieData.webInfo.Deals[i].UserUID + "'");
                                                                                            Manegerdata.Add("RecipientId", "'" + RicevieData.webInfo.Deals[i].OperatorId + "'");
                                                                                        }

                                                                                        var userList = myAcess.select("AspNetUsers", "Balance", string.Format("Id = '{0}'", RicevieData.webInfo.Deals[i].UserUID));
                                                                                        decimal tempBalance = Convert.ToDecimal(userList[0]["Balance"]);

                                                                                        Manegerdata.Add("OperatorId", "'" + RicevieData.webInfo.Deals[i].OperatorId + "'");
                                                                                        Manegerdata.Add("OperatorEntityId", "'" + RicevieData.webInfo.Deals[i].OperatorEntityId + "'");
                                                                                        Manegerdata.Add("EntityID", "'" + RicevieData.webInfo.Deals[i].EntityId.ToString() + "'");
                                                                                        Manegerdata.Add("BeforeBalance", "'" + (tempBalance - (decimal)RicevieData.webInfo.Deals[i].Amount).ToString() + "'");
                                                                                        Manegerdata.Add("Amount", "'" + Math.Abs(Math.Round((decimal)RicevieData.webInfo.Deals[i].Amount, AccuracyDigit)).ToString() + "'");
                                                                                        Manegerdata.Add("IP", "'" + RicevieData.webInfo.Deals[i].IP_Address + "'");
                                                                                        Manegerdata.Add("TimeStamp", GetLogTimeStamp(DateTime.Now).ToString());
                                                                                        //myAcess.insert("ManagerTradeRecord", Manegerdata);
                                                                                        OperTionDBBox TempData = new OperTionDBBox(OpertionCode.insert, "ManagerTradeRecord", Manegerdata);
                                                                                        lock (Program.opertionDBBoxs)
                                                                                        {
                                                                                            Program.opertionDBBoxs.Add(TempData);
                                                                                        }
                                                                                        //=======================================================================
                                                                                    }

                                                                                    //更新管理者DB資料
