                                                            #region WebCommand
                                                            case WebCode.WebCommand:
                                                                {
                                                                    bool workDone = false;
                                                                    string webCommand = RicevieData.webInfo.WebCommand.Split(',')[0];
                                                                    //MyConsole.WriteLine("WebCommand : Command=" + webCommand + ", GameName=" + RicevieData.webInfo.GameName);
                                                                    if (webCommand == "BigWaterPumpIn" || webCommand == "BigWaterDrainOut" || webCommand == "IndepBigWaterPumpIn" || webCommand == "IndepBigWaterDrainOut") //大水庫抽放水
                                                                    {
                                                                        bool pumpIn;
                                                                        int poolType;
                                                                        if (webCommand == "BigWaterPumpIn") { poolType = 0; pumpIn = true; } //poolType (0=常規水庫)
                                                                        else if (webCommand == "BigWaterDrainOut") { poolType = 0; pumpIn = false; }
