                                                if (entity.RebateValid)
                                                {
                                                    DBCache.GetRebateWallet(userData, entity, ref tmpData.Data);
                                                }

                                                m_ListenGameServerSocket.SendMessage(token, Message.SerializrToStream(tmpData));
                                            }
                                            if (RicevieData.Command == "RebatePullRequest") //Client要求 返水領獎
                                            {
                                                //處理玩家領取返水
                                                MyConsole.WriteLine($"    玩家[{RicevieData.UserUID}]要求領取返水");
                                                int userUid = RicevieData.UserUID;
                                                //UserData userData = DBCache.Getuser(userUid);
                                                //var entity = DBCache.GetEntityData(userData.EntityId);
                                                Dictionary<string, string> rebateInfo = new();
                                                int result = DBCache.JudgeRebateGet(userUid, out string rewardResult, out double getRebate, ref rebateInfo);

                                                //返回 領取返水 結果
                                                var tmpData = new CommonInfoData();
                                                tmpData.Command = RicevieData.Command;
                                                tmpData.UserUID = RicevieData.UserUID;
                                                tmpData.GameServer = RicevieData.GameServer;
                                                tmpData.Message = rewardResult;
                                                tmpData.Data = rebateInfo;

                                                m_ListenGameServerSocket.SendMessage(token, Message.SerializrToStream(tmpData));

                                                MyConsole.WriteLine($"    玩家[{RicevieData.UserUID}]要求領取返水結果: {rewardResult}");

                                                if (result == 0) //領取成功
                                                {
                                                    //發送更新玩家Credit
                                                    //m_ListenGameServerSocket.SendMessage(token, Message.SerializrToStream(Message.Pack(
                                                    //    OperationCode.ManagerChangeClientCridet, ActorUpdataCode.UpdateCredit, userUid, getRebate, 0)));

                                                    m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(Message.Pack(
                                                        OperationCode.ManagerChangeClientCridet, ActorUpdataCode.UpdateCredit, userUid, getRebate, 0)));
                                                }
                                            }
                                            else if (RicevieData.Command == "GetRankResult")
                                            {
                                                //#250924 GetRankResult 玩家取榜單
                                                MyConsole.WriteLine($"玩家[{RicevieData.UserUID}]取榜單");
                                                var tmpData = new CommonInfoData();
                                                tmpData.Command = RicevieData.Command;
                                                tmpData.UserUID = RicevieData.UserUID;
                                                tmpData.GameServer = GameServerCode.None; //None=DBCache
                                                tmpData.Data = new Dictionary<string, string>();

                                                UserData userData = DBCache.Getuser(RicevieData.UserUID);
                                                var entity = DBCache.GetEntityData(userData.EntityId);
                                                DBCache.GetRankEventTopData(userData, entity, ref tmpData);

                                                m_ListenGameServerSocket.SendMessage(token, Message.SerializrToStream(tmpData));
                                            }
                                            else if (RicevieData.Command == "UpdataCalcPool")
                                            {
                                                //MyConsole.WriteLine($"更新[{RicevieData.GameServer}]共用機率資料");
                                                DBCache.UpdataGameServerCalcPool(RicevieData.GameServer, RicevieData.Data);
                                            }
                                        }
                                    }
                                    break;
                            }

                        }
                    }
                    catch (Exception e)
                    {
                        Console.Error.WriteLine(
                            $"HandleMessage failed. Type={e.GetType().FullName}, Message={e.Message}, StackTrace={e.StackTrace}");
                    }

                }

                Thread.Sleep(1);
            }
        }

        /// <summary>製作玩家登入回應封包 (DB->Login->Client)</summary>
        static GameData LoginGameDataMake(UserData tempUserData, EntityData entity, GameData ricevieData)
        {
            List<GameData.ClassType> tempClassType = new List<GameData.ClassType>();
            tempClassType.Add(GameData.ClassType.userData);
            tempClassType.Add(GameData.ClassType.jpInfo);
            tempClassType.Add(GameData.ClassType.ExtraData);
            GameData Sendata = new GameData(tempClassType);
            Sendata.operationCode = OperationCode.Login;
            Sendata.errorCode = ErrorCode.Ok;
            Sendata.DebugMessage = "";

            Sendata.userData.memberUniquelID = tempUserData.UserUID;
            Sendata.userData.entityUID = tempUserData.EntityId;
            Sendata.userData.memberID = tempUserData.UserID;
            Sendata.userData.memberPW = tempUserData.UserPwd;
            Sendata.userData.Nickname = tempUserData.Nickname;
            try
            {
                if (DBCache.TryGetBatchDepositV2BalanceBaseline(
                    tempUserData.UserUID,
                    out double balance,
                    out double sessionId,
                    out long baselineFenceId))
                {
                    Sendata.userData.SessionID = sessionId;
                    Sendata.userData.Balnce = balance;
                    Sendata.userData.BaselineFenceId = baselineFenceId;
                }
                else
                {
                    Sendata.errorCode = ErrorCode.IllegalUser;
                    Sendata.DebugMessage = "Unable to create authoritative balance baseline.";
                }
            }
            catch (Exception exception)
            {
                Sendata.errorCode = ErrorCode.InvalidOperation;
                Sendata.DebugMessage = exception.Message;
                BatchDepositV2OperationalLog.Write("error", "baseline", "login_baseline_query_failed",
                    new { userUid = tempUserData.UserUID, error = exception.Message });
            }
            Sendata.userData.Sex = tempUserData.Sex;
            Sendata.userData.ratio = 100;
            Sendata.userData.Energy = tempUserData.EnergyBar;
            Sendata.userData.Star = tempUserData.Star;

            Sendata.userData.Profit = 0;
            Sendata.userData.Pool = 0;
            Sendata.userData.ExtInfo = DBCache.GetCurrencyLobbySetting(entity) + DBCache.GetEntityServiveInfo(tempUserData.EntityId); //LobbyInfo
            Sendata.userData.NewPW = DBCache.JPSettingData.GetLittleJPStr(); //LittleJP

            Sendata.userData.RemoteEndPoint = ricevieData.userData.RemoteEndPoint;
            Sendata.userData.SysTemText = DBCache.RandomText();

            //MARKLU: JP廣播 Login
            Sendata.jpInfo.Super = DBCache.superJP.InitPoint;
            Sendata.jpInfo.Mege = DBCache.megaJP.InitPoint;
            Sendata.jpInfo.Major = DBCache.majorJP.InitPoint;
            Sendata.jpInfo.Minor = DBCache.minorJP.InitPoint;
            Sendata.jpInfo.SuperBase = DBCache.JPSettingData.SuperInit;  //20201008
            Sendata.jpInfo.MegeBase = DBCache.JPSettingData.MegaInit;
            Sendata.jpInfo.MajorBase = DBCache.JPSettingData.MajorInit;
            Sendata.jpInfo.MinorBase = DBCache.JPSettingData.MinorInit;
            Sendata.jpInfo.HalfJPGetMinBet = DBCache.JPSettingData.HalfJPGetMinBet;
            Sendata.jpInfo.AllJPGetMinBet = DBCache.JPSettingData.AllJPGetMinBet;
            Sendata.jpInfo.JPGetLevelCount = DBCache.JPSettingData.FJP_Level;

            //GameServer版本資訊
            Sendata.extraData.Data3 = DBCache.GetGameServerVersionList();

            //第三方支付, H5相關設定
            Sendata.webInfo = new WebInfo();
            Sendata.webInfo.CalculateInfo = new List<string>();
            Sendata.webInfo.CalculateInfo.Add(entity.GetSysSettingString());

            //海王押分設定 (大廳遊戲ICON要用)
            Sendata.extraData.Data2 = DBCache.LoginGetGameBetMinMax(tempUserData.EntityId);

            //額外資料
            Sendata.extraData.Data4 = DBCache.LoginGetExtraInfo(tempUserData, entity);

            //Sendata.LockGameList; //由Login在轉發前補充此資訊

            return Sendata;
        }

        /// <summary>製作GameServer驗證玩家回應封包 (DB->LoginServer->GameServer)</summary>
        static VerificationData VerificationDataMake(UserData TempData, VerificationData ricevieData)
        {
            //玩家進入GameServerRoom驗證
            VerificationData Sendata = new VerificationData();
            Sendata.operationCode = OperationCode.VerificationDB;
            Sendata.errorCode = ErrorCode.Ok;
            Sendata.gameServerCode = ricevieData.gameServerCode;
            Sendata.IP = "";
            Sendata.memberUniquelID = TempData.UserUID;
            Sendata.entityUID = TempData.EntityId;
            Sendata.memberID = TempData.UserID;
            Sendata.memberPW = TempData.UserPwd;
            Sendata.Sex = TempData.Sex;
            Sendata.Nickname = TempData.Nickname;
            Sendata.Energy = TempData.EnergyBar;
            Sendata.Star = TempData.Star;
            Sendata.Profit = 0;
            Sendata.Pool = 0;

            string DataTxt = TempData.GetExtraDataInfo(ricevieData.gameServerCode) + DBCache.GetEntityExtraDataInfo(TempData.EntityId);
            Sendata.ExtInfo = DataTxt;

            //紅包炒場 #250211  (玩家進入 Server 驗證時, 在此重置 紅包出牌旗號) (玩家IP資訊)
            DBCacheData DbcacheData = DBCache.PlayerEnterGameServer(TempData, ricevieData.gameServerCode);
            Sendata.DbcacheData = DbcacheData;

            try
            {
                if (DBCache.TryGetBatchDepositV2BalanceBaseline(
                    TempData.UserUID,
                    out double balance,
                    out double sessionId,
                    out long baselineFenceId))
                {
                    Sendata.Balnce = balance;
                    Sendata.SessionID = sessionId;
                    Sendata.BaselineFenceId = baselineFenceId;
                }
                else
                {
                    Sendata.errorCode = ErrorCode.IllegalUser;
                }
            }
            catch (Exception exception)
            {
                Sendata.errorCode = ErrorCode.InvalidOperation;
                BatchDepositV2OperationalLog.Write("error", "baseline", "verification_baseline_query_failed",
                    new { userUid = TempData.UserUID, error = exception.Message });
            }

            return Sendata;
        }

