        /// <summary>通知Login和Game伺服踢掉玩家</summary>
        static void BlockOutOnePlayer(UserData tempUser)
        {
            if (tempUser != null && tempUser.Usersituation != 0)
            {
                if (tempUser.Usersituation == 1)
                {
                    //傳給LoginServer踢掉這個人
                    m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.LoginServer, Message.SerializrToStream(Message.Pack(OperationCode.QuitServer, tempUser.UserUID)));
                }
                else
                {
                    //傳給LoginServer踢掉這個人
                    m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.LoginServer, Message.SerializrToStream(Message.Pack(OperationCode.QuitServer, tempUser.UserUID)));
                    //傳給GameServer踢掉這個人
                    //m_ListenGameServerSocket.SendMessage(m_ListenGameServerSocket.GameServerList[tempUser.Usersituation - 2], Message.SerializrToStream(Message.Pack(OperationCode.QuitServer, tempUser.UserUID)));
                    GameServerCode gcode = (GameServerCode)tempUser.Usersituation;

                    lock (m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
                    {
                        foreach (AsyncUserToken gtoken in m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
                        {
                            if (gtoken.gameType == gcode)
                            {
                                m_ListenGameServerSocket.SendMessage(gtoken, Message.SerializrToStream(Message.Pack(OperationCode.QuitServer, tempUser.UserUID)));
                                break;
                            }
                        }
                    }
                }
            }
        }

