        public static long GetLogSearchIndex(DateTime now, int userUid)
        {
            DateTime basetime = new DateTime(2020, 1, 1);
            int timeIndex = (now.Date - basetime).Days;
            long searchIndex = ((long)userUid * 100000) + (long)timeIndex;
            return searchIndex;
        }
        public static int GetLogTimeStamp(DateTime now)
        {
            return ((now.Year * 10000) + (now.Month * 100) + now.Day);
        }


