        //static double megaJpAccum = 0;
        /// <summary>JP自動增值</summary>
        static double JpAccumValue = 0;
        private static void BroadCastJP(object state)
        {
            //List<int> tempEndpoint = DBCache.GetJPEndSocre();
            Random mRand = new Random(Guid.NewGuid().GetHashCode());
            DBCache.superJP.GetWeights(DateTime.Now.Hour);
            DBCache.megaJP.GetWeights(DateTime.Now.Hour);
            DBCache.majorJP.GetWeights(DateTime.Now.Hour);
            DBCache.minorJP.GetWeights(DateTime.Now.Hour);
            DBCache.superJP.GetFrequencyIndex();
            DBCache.megaJP.GetFrequencyIndex();
            DBCache.majorJP.GetFrequencyIndex();
            DBCache.minorJP.GetFrequencyIndex();

            JpAccumValue = DBCache.GetJPAccFactor();

            while (true)
            {
                if(MySqlErrorFg == false)
                {
                    try
                    {
                        bool updateJP = false;
                        #region SuperJP
                        //=======================================SuperJP增值頻率用=============================================
                        if (Superfrequency == 0)
                        {
                            if (mRand.Next(1000) < 200)
                            {
                                DBCache.superJP.GetWeights(DateTime.Now.Hour);
                                DBCache.superJP.GetFrequencyIndex();
                            }
                            SuperTime = DBCache.superJP.frequencyindex * 2;
                        }

                        if (Superfrequency <= SuperTime)
                        {
                            Superfrequency++;
                        }

                        if (Superfrequency >= SuperTime)
                        {
                            Superfrequency = 0;

                            if (DBCache.superJP.InitPoint < DBCache.JPSettingSuperEnd)
                            {
                                //DBCache.superJP.InitPoint += 0.01f;
                                DBCache.superJP.InitPoint += JpAccumValue;
                                DBCache.superJP.InitPoint = Math.Round(DBCache.superJP.InitPoint, AccuracyDigitJP);
                            }

                            updateJP = true;
                        }
                        //========================================================================================================
                        #endregion

                        #region MegaJP MajorJP MinorJP
                        //=======================================其餘的JP增值頻率用================================================
                        if (frequency == 0)
                        {
                            //重算權重
                            if (mRand.Next(1000) < 200)
                            {
                                DBCache.megaJP.GetWeights(DateTime.Now.Hour);
                                DBCache.majorJP.GetWeights(DateTime.Now.Hour);
                                DBCache.minorJP.GetWeights(DateTime.Now.Hour);
                                DBCache.megaJP.GetFrequencyIndex();
                                DBCache.majorJP.GetFrequencyIndex();
                                DBCache.minorJP.GetFrequencyIndex();
                            }
                        }

                        if (frequency <= 40)
                        {
                            int remainder = frequency % 8;

                            //如果MEGA的增值頻率在範圍內
                            if (DBCache.megaJP.frequencyindex - remainder > 0 && DBCache.megaJP.InitPoint < DBCache.JPSettingMegaEnd)
                            {
                                //megaJpAccum += 0.0034f;
                                //if (megaJpAccum >= 0.01f)
                                {
                                    //megaJpAccum -= 0.01f;
                                    //DBCache.megaJP.InitPoint += 0.01f;
                                    DBCache.megaJP.InitPoint += JpAccumValue;
                                    DBCache.megaJP.InitPoint = Math.Round(DBCache.megaJP.InitPoint, AccuracyDigitJP);
                                }
                            }

                            //如果MAJOR的增值頻率在範圍內
                            if (DBCache.majorJP.frequencyindex - remainder > 0 && DBCache.majorJP.InitPoint < DBCache.JPSettingMajorEnd)
                            {
                                //DBCache.majorJP.InitPoint += 0.02f;
                                DBCache.majorJP.InitPoint += JpAccumValue;
                                DBCache.majorJP.InitPoint = Math.Round(DBCache.majorJP.InitPoint, AccuracyDigitJP);
                            }

                            //如果MINOR的增值頻率在範圍內
                            if (DBCache.minorJP.frequencyindex - remainder > 0 && DBCache.minorJP.InitPoint < DBCache.JPSettingMinorEnd)
                            {
                                //DBCache.minorJP.InitPoint += 0.01f;
                                DBCache.minorJP.InitPoint += JpAccumValue;
                                DBCache.minorJP.InitPoint = Math.Round(DBCache.minorJP.InitPoint, AccuracyDigitJP);
                            }

                            frequency++;
                        }

                        if (frequency >= 40)
                        {
                            frequency = 0;
                            updateJP = true;
                        }
                        //========================================================================================================
                        #endregion

                        if (updateJP)
                        {
                            //回寫DB
                            DBCache.UpdatejpCountData();
                            //傳給Loginserver新值
                            SendJPMessageToLogin();
                        }
                    }
                    catch (Exception ex)
                    {
                        MyConsole.WriteLine(ex.Message, Console.ForegroundColor = ConsoleColor.Red);
                        MyConsole.WriteLine(ex.StackTrace);
                    }
                }

                Thread.Sleep(125);
            }
        }
        /// <summary>傳給 Loginserver JP 新值</summary>
        private static void SendJPMessageToLogin()
        {
            //MARKLU: JP廣播 傳新值 (金庫) 20201008
            if (m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer != null)
            {
                m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(Message.Pack(
                    OperationCode.BroadcastJP,
                    DBCache.superJP.InitPoint,
                    DBCache.megaJP.InitPoint,
                    DBCache.majorJP.InitPoint,
                    DBCache.minorJP.InitPoint,
                    //DBCache.JPSettingData.SuperInit,
                    //DBCache.JPSettingData.MegaInit,
                    //DBCache.JPSettingData.MajorInit,
                    //DBCache.JPSettingData.MinorInit,
                    DBCache.JpRealData.TreasuryStatus)));
            }
        }

