        static bool AnnoPostBCAct = false; //廣播啟動旗號
        static bool AnnoPostBCChg = false; //廣播變更
        static ushort AnnoPostBCnt = 0; //廣播次數
        /// <summary>廣播公告訊息 (Alibaba版)</summary>
        public static void BroadCastAnnoPostTask()
        {
            //#250325 公告訊息
            List<GameData.ClassType> tempClassType = new List<GameData.ClassType> { GameData.ClassType.SystemCommand };
            GameData Sendata = new GameData(tempClassType);
            Sendata.errorCode = ErrorCode.Ok;
            Sendata.operationCode = OperationCode.BroadcastSystemCommand;
            Sendata.systemCommandData.Command = SystemCommand.ChangeNotification;

            string text = DBCache.GetAnnoPostMessage();
            int serialNo = DBCache.GetAnnoPostSN();
            Sendata.systemCommandData.Message = new List<string> { text };
            Sendata.systemCommandData.DataList = new List<int> { serialNo };

            AnnoPostBCnt = 0;

            int delay = 0;

            while (true)
            {
                if (delay > 0) delay--;

                if (delay <= 0 || AnnoPostBCChg)
                {

                    if (AnnoPostBCChg) //廣播中途有變更, 重設廣播資料
                    {
                        AnnoPostBCChg = false;
                        AnnoPostBCnt = 0;
                        string text2 = DBCache.GetAnnoPostMessage();
                        int serialNo2 = DBCache.GetAnnoPostSN();
                        Sendata.systemCommandData.Message[0] = text2;
                        Sendata.systemCommandData.DataList[0] = serialNo2;
                    }

                    if (m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer != null)
                    {
                        m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(Sendata));
                    }

                    delay = 20; ////每20秒重發一次
                    AnnoPostBCnt++;
                    if (AnnoPostBCnt >= 3) //共發3次
                    {
                        break;
                    }
                    MyConsole.WriteLine($"RefreshAnnoPost : 第{AnnoPostBCnt}次廣播");
                }

                Thread.Sleep(1000);
            }

            AnnoPostBCAct = false;
            MyConsole.WriteLine($"RefreshAnnoPost : 結束廣播");
        }
