        /// <summary>浮點數誤差容許值</summary>
        const double _EpsValue = 0.000001;

        /// <summary>老虎機 驗證玩家押分(單人遊戲)</summary>
        static bool CheckSlotGameBetin(GameData RicevieData, GameServerCode serverCode, int machineUid,
                            List<int> tempillegalUser,
                            List<int> tempillegalMinStartRate,
                            Dictionary<int, Equipment> tempUserEnergy,
                            Dictionary<int, RedEnvelope> tempUserRedEnvelope,
                            double minTotalBet, double maxTotalBet)
        {
            if (RicevieData.betInfo.AllRoomActorBetinfo != null && RicevieData.betInfo.AllRoomActorBetinfo.Count > 0)
            {
                bool okfg = true;
                foreach (KeyValuePair<int, double[]> temp in RicevieData.betInfo.AllRoomActorBetinfo)
                {
                    var tempDBUser = DBCache.Getuser(temp.Key);
                    if (tempDBUser != null)
                    {
                        double tempAllBet = Math.Round(temp.Value[0], 4);

                        if (RicevieData.betInfo.GameMode == 0 //常規遊戲模式才須判斷
                            && (tempAllBet < (minTotalBet - _EpsValue) || tempAllBet > (maxTotalBet + _EpsValue)))
                        {
                            tempillegalMinStartRate.Add(temp.Key);
                            okfg = false;
                            //MyConsole.WriteLine("押分不足:" + tempAllBet + ",  Min=" + minTotalBet + ", Max=" + maxTotalBet);
                        }

                        if ((tempDBUser.UserBalance + _EpsValue) - tempAllBet < 0)
                        {
                            tempillegalUser.Add(temp.Key);
                            okfg = false;
                            //MyConsole.WriteLine("押分錯誤");
                        }

                        if (okfg)
                        {
                            Equipment userEquipment = DBCache.EnergyCount(tempAllBet, temp.Key);
                            tempUserEnergy.Add(temp.Key, userEquipment);

                            if (RicevieData.betInfo.GameMode == 0) //常規遊戲模式才需記
                            {
                                tempDBUser.CheckUserLastBet(tempAllBet);
                            }

                            if (RicevieData.betInfo.AskRedEnvelope.ContainsKey(temp.Key) && RicevieData.betInfo.AskRedEnvelope[temp.Key] == true)
                            {
                                var entity = DBCache.GetEntityData(tempDBUser.EntityId);
                                if (CheckWebRedEnvelope(tempDBUser, temp.Key, GameTypeCode.Slot, serverCode, machineUid, tempAllBet, entity, out RedEnvelope redEnv))
                                {
                                    tempUserRedEnvelope.Add(temp.Key, redEnv);
                                }
                            }
                        }
                    }
                    else
                    {
                        okfg = false; //玩家不存在
                    }
                    //MyConsole.WriteLine("遊戲:" + gameType + " 機台:" + machineUid + ", 玩家:" + temp.Key + ", Bet:" + tempAllBet + ", Balance:" + Math.Round(tempUser.UserBalance, AccuracyDigit));
                    break;  //老虎機預設為單人遊戲, 因此直接Exit
                }
                return okfg;
            }
            return false;
        }

        /// <summary>押分機 驗證玩家押分</summary>
        static void CheckArcadGameBetin(GameData RicevieData, GameServerCode serverCode, int machineUid,
                            List<int> tempillegalUser,
                            List<int> tempillegalMinStartRate,
                            Dictionary<int, Equipment> tempUserEnergy,
                            Dictionary<int, RedEnvelope> tempUserRedEnvelope,
                            double minTotalBet, double maxTotalBet, double minStartTotalBet)
        {
            foreach (KeyValuePair<int, double[]> temp in RicevieData.betInfo.AllRoomActorBetinfo)
            {
                bool okfg = true;

                var tempDBUser = DBCache.Getuser(temp.Key);
                if (tempDBUser != null)
                {
                    bool rateLimitError = false;
                    double tempAllBet = 0;
                    minTotalBet -= _EpsValue;
                    maxTotalBet += _EpsValue;
                    minStartTotalBet -= _EpsValue;

                    for (int i = 0; i < temp.Value.Length; i++)
                    {
                        double bet = temp.Value[i];
                        tempAllBet += bet;

                        if (bet > 0 && (bet < minTotalBet || bet > maxTotalBet))
                        {
                            rateLimitError = true;
                        }
                    }

                    tempAllBet = Math.Round(tempAllBet, 4);

                    if ((tempDBUser.UserBalance + _EpsValue) - tempAllBet < 0)
                    {
                        tempillegalUser.Add(temp.Key);
                        okfg = false;
                        //Console.WriteLine("玩家 " + temp.Key + " 錢不足");
                    }

                    //MARKLU:押分不足測試
                    //Console.WriteLine("總押=" + tempAllBet + ", minStartRateLimit=" + minStartRateLimit + ", minRateLimit=" + minRateLimit + ", maxRateLimit=" + maxRateLimit + ", rateLimitError=" + rateLimitError);
                    if (rateLimitError || (tempAllBet < minStartTotalBet))  //高低押分錯誤 or 總押小於最低啟動押分
                    {
                        tempillegalMinStartRate.Add(temp.Key);
                        okfg = false;
                        //Console.WriteLine("玩家 " + temp.Key + " 押分不足");
                    }

                    if (okfg)
                    {
                        Equipment userEquipment = DBCache.EnergyCount(tempAllBet, temp.Key);
                        tempUserEnergy.Add(temp.Key, userEquipment);

                        if (RicevieData.betInfo.AskRedEnvelope.ContainsKey(temp.Key) && RicevieData.betInfo.AskRedEnvelope[temp.Key] == true)
                        {
                            var entity = DBCache.GetEntityData(tempDBUser.EntityId);
                            if (CheckWebRedEnvelope(tempDBUser, temp.Key, GameTypeCode.Arcade, serverCode, machineUid, tempAllBet, entity, out RedEnvelope redEnv))
                            {
                                tempUserRedEnvelope.Add(temp.Key, redEnv);
                            }
                        }
                    }
                }
                else
                {
                    tempillegalUser.Add(temp.Key);
                }
            }
        }

        /// <summary>打魚機 驗證玩家押分(單人遊戲)</summary>
        static bool CheckFishGameBetin(GameData RicevieData, GameServerCode serverCode, int machineUid,
                            List<int> tempillegalUser,
                            List<int> tempillegalMinStartRate,
                            Dictionary<int, Equipment> tempUserEnergy,
                            Dictionary<int, RedEnvelope> tempUserRedEnvelope,
                            double minTotalBet, double maxTotalBet)
        {
            if (RicevieData.betInfo.AllRoomActorBetinfo != null && RicevieData.betInfo.AllRoomActorBetinfo.Count > 0)
            {
                bool okfg = true;
                foreach (KeyValuePair<int, double[]> temp in RicevieData.betInfo.AllRoomActorBetinfo)
                {
                    var tempDBUser = DBCache.Getuser(temp.Key);
                    if (tempDBUser != null)
                    {
                        double tempAllBet = Math.Round(temp.Value[0], 4);

                        //打魚機不驗證高低押分, 因為傳來的不是單發子彈, 而是整批子彈
                        //if (tempAllBet < (minTotalBet - _EpsValue) || tempAllBet > (maxTotalBet + _EpsValue))
                        //{
                        //    tempillegalMinStartRate.Add(temp.Key);
                        //    okfg = false;
                        //    //MyConsole.WriteLine("押分不足:" + tempAllBet + ",  Min=" + minTotalBet + ", Max=" + maxTotalBet);
                        //}

                        //if (tempDBUser.UserBalance - tempAllBet < 0)
                        if ((tempDBUser.UserBalance + _EpsValue) - tempAllBet < 0)
                        {
                            bool illegal = true;
                            double crdiff = 0;
                            //因為魚機不是即時更新Credit, 因此當玩家沒錢時, 可能發生前端已經先把最後的贏分拿來玩, 但是後台尚未得到最後的贏分資訊, 造成押分錯誤
                            //因此在此處直接把最後的贏分加進來判斷
                            if (RicevieData.betInfo.AllRoomActorCreditInfo != null)
                            {
                                if (RicevieData.betInfo.AllRoomActorCreditInfo.ContainsKey(temp.Key))
                                {
                                    crdiff = RicevieData.betInfo.AllRoomActorCreditInfo[temp.Key]; //玩家本次差額(正值為贏, 負值為輸 win-bet) 
                                    if (tempDBUser.UserBalance + crdiff >= 0)
                                    {
                                        illegal = false;
                                    }
                                }
                            }

                            //MyConsole.WriteLine("玩家A[" + temp.Key + "]押分錯誤: DB餘額=" + tempDBUser.UserBalance + ", 差額=" + crdiff + ", 押分=" + tempAllBet); //UNDONE: 押分錯誤

                            if (illegal)
                            {
                                tempillegalUser.Add(temp.Key);
                                okfg = false;
                                double restCredit = tempDBUser.UserBalance; //+ crdiff;
                                MyConsole.WriteLine("玩家[" + temp.Key + "]押分錯誤: DB餘額=" + restCredit + ", 差額=" + crdiff + ", 押分=" + tempAllBet);
                            }
                        }

                        if (okfg)
                        {
                            Equipment userEquipment = DBCache.EnergyCount(tempAllBet, temp.Key);
                            tempUserEnergy.Add(temp.Key, userEquipment);

                            if (RicevieData.betInfo.AskRedEnvelope.ContainsKey(temp.Key) && RicevieData.betInfo.AskRedEnvelope[temp.Key] == true)
                            {
                                var entity = DBCache.GetEntityData(tempDBUser.EntityId);
                                if (CheckWebRedEnvelope(tempDBUser, temp.Key, GameTypeCode.Fish, serverCode, machineUid, tempAllBet, entity, out RedEnvelope redEnv))
                                {
                                    tempUserRedEnvelope.Add(temp.Key, redEnv);
                                }
                            }
                        }
                    }
                    else
                    {
                        okfg = false; //玩家不存在
                    }
                    //MyConsole.WriteLine("打魚機 機台:" + machineUid + ", 玩家:" + temp.Key + ", Bet:" + tempAllBet + ", Balance:" + Math.Round(tempDBUser.UserBalance, AccuracyDigit)); //UNDONE: 打魚機驗證押分
                    break;  //打魚機驗證時為 單人個別上傳, 因此直接Exit
                }
                return okfg;
            }
            return false;
        }
