        //MARKLU: WEB發遊戲紅包 函式
        private class RedEnvelopeCtrl
        {
            public int Action = 0;
            public RedEnvelope RedEnvInfo = new RedEnvelope();
            public int LimitTimer = 0;
        }
        private static List<RedEnvelopeCtrl> webRedEnvelopeList = new List<RedEnvelopeCtrl>();

        /// <summary>WEB發遊戲紅包逾時計時器</summary>
        private static void ForceRedEnvelopeWatchDogTimer(object state)
        {
            while (true)
            {
                Thread.Sleep(60000); //1分鐘
                if (webRedEnvelopeList.Count > 0)
                {
                    for (int i = 0; i < webRedEnvelopeList.Count; i++)
                    {
                        if (webRedEnvelopeList[i].Action == 1) //紅包尚未發出
                        {
                            webRedEnvelopeList[i].LimitTimer++;
                            if (webRedEnvelopeList[i].LimitTimer >= 10) //10分鐘
                            {
                                UpdateEnforceRedEnvelopeLog(webRedEnvelopeList[i].RedEnvInfo.LogUid, "", "逾時");
                                webRedEnvelopeList.RemoveAt(i);
                                break;
                            }
                        }
                    }
                }
            }
        }
        /// <summary>回寫WEB強出遊戲紅包Log紀錄表</summary>
        private static void UpdateEnforceRedEnvelopeLog(int logUid, string playerIp, string result)
        {
            Dictionary<string, string> udata = new Dictionary<string, string>();
            udata.Add("Result", "'" + result + "'");
            udata.Add("PlayerIP", "'" + playerIp + "'");

            OperTionDBBox TempOperTionDBBox = new OperTionDBBox(OpertionCode.update1, "EnforceRedEnvelopeLog", udata, "UID", "'" + logUid + "'");
            lock (Program.opertionDBBoxs)
            {
                opertionDBBoxs.Add(TempOperTionDBBox);
            }
        }
        /// <summary>WEB強出遊戲紅包移除登錄</summary>
        private static bool RemoveWebRedEnvelope(int logUid)
        {
            //MyConsole.WriteLine("WEB強出遊戲紅包移除登錄");
            if (webRedEnvelopeList.Count > 0)
            {
                for (int i = 0; i < webRedEnvelopeList.Count; i++)
                {
                    if (webRedEnvelopeList[i].RedEnvInfo.LogUid == logUid)
                    {
                        //webRedEnvelopeList.Remove(webRedEnvelopeList[i]);
                        webRedEnvelopeList.RemoveAt(i);
                        return true;
                    }
                }
            }
            return false;
        }
        /// <summary>WEB強出遊戲紅包登錄</summary>
        private static bool AddWebRedEnvelope(int logUid, int userUid, int machineUid, double envelopeValue)
        {
            if (logUid > 0 && (userUid > 0 || machineUid > 0) && envelopeValue > 0)
            {
                RedEnvelopeCtrl redEnvCtrl = new RedEnvelopeCtrl();
                redEnvCtrl.RedEnvInfo.LogUid = logUid;
                redEnvCtrl.RedEnvInfo.UserUid = userUid;
                redEnvCtrl.RedEnvInfo.MachineUid = machineUid;
                redEnvCtrl.RedEnvInfo.EnvelopeValue = envelopeValue;
                redEnvCtrl.Action = 1; //紅包已登錄
                webRedEnvelopeList.Add(redEnvCtrl);
                return true;
            }
            return false;
        }
        /// <summary>遊戲紅包發出判斷</summary>
        private static bool CheckWebRedEnvelope(UserData userData, int userUid, GameTypeCode gameType, GameServerCode serverCode, int machineUid, double allBet, EntityData entity, out RedEnvelope redEnv)
        {
            //MARKLU: 發紅包
            //檢查WEB強制發紅包
            //MyConsole.WriteLine("玩家[" + userUid + "]要求遊戲紅包");
            if (webRedEnvelopeList.Count > 0)
            {
                lock (webRedEnvelopeList)
                {
                    foreach (RedEnvelopeCtrl info in webRedEnvelopeList)
                    {
                        if (info.Action == 1 && (
                           (info.RedEnvInfo.UserUid > 0 && info.RedEnvInfo.UserUid == userUid) ||
                           (info.RedEnvInfo.MachineUid > 0 && info.RedEnvInfo.MachineUid == machineUid)))
                        {
                            info.Action = 2; //紅包已發出
                            redEnv = new RedEnvelope
                            {
                                LogUid = info.RedEnvInfo.LogUid,
                                MachineUid = info.RedEnvInfo.MachineUid,
                                UserUid = info.RedEnvInfo.UserUid,
                                EnvelopeValue = info.RedEnvInfo.EnvelopeValue
                            };
                            //MyConsole.WriteLine("WEB強制發紅包");
                            return true;
                        }
                    }
                }
            }

            //機率發紅包
            double redBonus = DBCache.GameRedEnvelopeCalculate(allBet);
            if (redBonus > 0)
            {
                redEnv = new RedEnvelope
                {
                    LogUid = 0,  //LogUid=0, 表示紅包由 機率 發出
                    MachineUid = 0,
                    UserUid = 0,
                    EnvelopeValue = redBonus
                };
                //MyConsole.WriteLine("機率發紅包");
                return true;
            }

            //紅包炒場發紅包 #250211
            redBonus = DBCache.FeverRedBonusCalculate(userData, allBet, gameType, serverCode, machineUid, entity);
            if (redBonus > 0)
            {
                redEnv = new RedEnvelope
                {
                    LogUid = _FeverRedBns,  //LogUid=-1, 表示紅包由 紅包炒場 發出
                    MachineUid = 0,
                    UserUid = 0,
                    EnvelopeValue = redBonus
                };
                //MyConsole.WriteLine($"紅包炒場發紅包:{redBonus}, 機台={machineUid}, 玩家={userData.UserID}, 押分={allBet}"); //UNDONE: 紅包炒場發紅包
                return true;
            }

            //沒有紅包
            redEnv = null;
            return false;
        }
