        /// <summary>將玩家返水設定在Equipment裡面</summary>
        static void GetRebateWalletInfo(ref Dictionary<int, Equipment> tempUserEnergy)
        {
            //#250807 玩家返水 (設定回傳GameServer Equipment)
            if (tempUserEnergy != null && tempUserEnergy.Count > 0)
            {
                foreach (var info in tempUserEnergy)
                {
                    int userUid = info.Key;
                    UserData userData = DBCache.Getuser(userUid);
                    var entity = DBCache.GetEntityData(userData.EntityId);
                    if (entity.RebateValid)
                    {
                        //以下返水資料會由 GameServer 轉發給玩家
                        info.Value.CommandType = "Rebate";
                        info.Value.ExtInfo = new();
                        //DBCache.GetRebateInfo(userData, entity, ref info.Value.ExtInfo);
                        DBCache.GetRebateWallet(userData, entity, ref info.Value.ExtInfo);
                    }
                }
            }
        }

