        /// <summary>返水結算與廣播 (每秒呼叫10次)</summary>
        static void BroadCastRebateProc()
        {
            if (!DBCache.InitEntityOk) return;

            //返水 #250807
            DBCache.RebateSettlementProcess();

            List<int> boardList = DBCache.GetRebateBroadcastPlayerList();

            if (boardList != null && boardList.Count > 0)
            {
                foreach (int userUid in boardList)
                {
                    UserData userData = DBCache.Getuser(userUid);

                    if (userData.Usersituation > 0) //在線玩家
                    {
                        EntityData entity = DBCache.GetEntityData(userData.EntityId);
                        var extraInfo = new Dictionary<string, string>();
                        DBCache.GetRebateInfo(userData, entity, ref extraInfo);

                        BroadCastRebate(extraInfo, userUid);
                    }
                }
            }
        }
