        private static bool JpDebugShow = true;

        /// <summary>JP計算線程</summary>
        private static void JPCalculate(object state)
        {
            DBCache.GetRealJPOutTimes(out superOutCtrl.ActFg, out superOutCtrl.OutTime,
                                   out megaOutCtrl.ActFg, out megaOutCtrl.OutTime,
                                   out majorOutCtrl.ActFg, out majorOutCtrl.OutTime,
                                   out minorOutCtrl.ActFg, out minorOutCtrl.OutTime);

            while (true)
            {
                try
                {
                    BroadCastRebateProc();

                    JPCDelayTimer0++;
                    if (JPCDelayTimer0 > 20) //2秒
                    {
                        JPCDelayTimer0 = 0;
                        JPCalculateProc();
                        TreasuryCalculateProc();
                        JPActionTimerWatchDog();
                        SystemServiceTimeCheck();
                        DBCache.RebateSettlementProc(); //返水 #250807
                        DBCache.CheckTopPlayKeepDay();
                        OffLineUserProc();

                        JPCDelayTimer1++;
                        if (JPCDelayTimer1 > 100) //200秒
                        {
                            JPCDelayTimer1 = 0;
                            DBCache.CheckUserGameDateKeep30Day();
                            DBCache.CheckReportGameDateKeep90Day();

                            if (DBCache.CountryOverDayJudge())
                            {
                                //MARKLU: 每日工作處理
                                DBCache.FeverRedBonusOverDayProc(); //紅包炒場 #250211

                                DBCache.RebateOverDayProc(); //返水 #250807

                                MyConsole.WriteLine($"AnnoPost : 每日公告排行榜重發"); //每日公告排行榜重發
                                DBCache.GetDBAnnouncePostTable(); //重設公告排行榜 #250325
                                BroadCastAnnoPostMessage(); //重發公告

                                DBCache.ResetAllUserKeyInOutRec(); //#251112
                            }
                        }
                    }
                    Thread.Sleep(100);
                }
                catch (Exception ex)
                {
                    MyConsole.WriteLine(ex.Message, Console.ForegroundColor = ConsoleColor.Red);
                    MyConsole.WriteLine(ex.StackTrace);
                }
            }
        }

        static int JPCDelayTimer0 = 1000;
        static int JPCDelayTimer1 = 1000;
        /// <summary>斷線玩家延遲處理列表</summary>
        static Dictionary<int, int> OffLineUserList = new Dictionary<int, int>();
        /// <summary>斷線玩家加入延遲處理列表</summary>
        static void AddOffLineUser(int userUid)
        {
            lock (OffLineUserList)
            {
                if (!OffLineUserList.ContainsKey(userUid))
                {
                    OffLineUserList.Add(userUid, 0);
                    //MyConsole.WriteLine("加入斷線玩家:" + userUid);
                }
            }
        }
        /// <summary>斷線玩家延遲處理程序</summary>
        static void OffLineUserProc()
        {
            if (OffLineUserList.Count > 0)
            {
                List<int> doneUser = new List<int>();
                lock (OffLineUserList)
                {
                    int[] userList = OffLineUserList.Keys.ToArray();
                    for (int i = 0; i < userList.Length; i++)
                    {
                        int userUid = userList[i];
                        OffLineUserList[userUid]++;
                        if (OffLineUserList[userUid] >= 2) //約2~4秒
                        {
                            doneUser.Add(userUid);
                        }
                    }
                }

                if (doneUser.Count > 0)
                {
                    lock (OffLineUserList)
                    {
                        foreach (int userUid in doneUser)
                        {
                            OffLineUserList.Remove(userUid);
                            //MyConsole.WriteLine("移除斷線玩家:" + userUid);
                        }
                    }
                }
            }
        }

        static int checkDelayTimer = 0;
        static int jpJudgeDuty = 0;
        //static int superTimerPrev = 0;
        //static int superTimerEvnCnt = 0;
        //static int megaTimerPrev = 0;
        //static int majorTimerPrev = 0;
        //static int minorTimerPrev = 0;

        //static int minorOutMinMin = 2;
        //static int minorOutMaxMin = 5;
        //static bool minorOutSetFg = false;
        //static DateTime minorOutTime;

        /// <summary>JP放出計算</summary>
        private static void JPCalculateProc()
        {
            if (checkDelayTimer > 0 && checkDelayTimer < 2000)
            {
                checkDelayTimer--;
                return;
            }

            jpJudgeDuty++;
            if (jpJudgeDuty >= 4)
            {
                jpJudgeDuty = 0;
            }

            //MARKLU: JP放出計算
            JpAward outJp = JpAward.None;
            DateTime dtNow = DateTime.Now;

            if (minorOutCtrl.ActFg)
            {
                if (jpJudgeDuty == 0 && CheckNoSameJPCommand(JpAward.MINOR))
                {
                    if (minorOutCtrl.CompareOutTime(dtNow))
                    {
                        if (DBCache.JPSettingData.IsBigWater_MINOR)
                        {
                            outJp = JpAward.MINOR;
                            if (JpDebugShow) MyConsole.WriteLine("出JP獎 : MINOR", Console.ForegroundColor = ConsoleColor.White);
                        }
                        else
                        {
                            minorOutCtrl.ActFg = false;
                            DBCache.SetMinorRealJPOutTimes(minorOutCtrl.ActFg, minorOutCtrl.OutTime);
                            if (JpDebugShow) MyConsole.WriteLine("JP獎 MINOR 鎖住不出", Console.ForegroundColor = ConsoleColor.White);
                        }
                    }
                }
            }
            else
            {
                //DBCache.JPSettingData.BigWater_MINOR_DL
                minorOutCtrl.SetOutTimeRange(DBCache.JPSettingData.BigWater_MINOR_DL, DBCache.JPSettingData.BigWater_MINOR_HL, DBCache.JPSettingData.BigWater_MINOR_ML,
                                          DBCache.JPSettingData.BigWater_MINOR_DU, DBCache.JPSettingData.BigWater_MINOR_HU, DBCache.JPSettingData.BigWater_MINOR_MU);
                //minorOutCtrl.SetOutTimeRange(0,0,1,  0,0,3); //UNDONE: 測試暫定1~3分
                minorOutCtrl.SetNextOutTime();
                DBCache.SetMinorRealJPOutTimes(minorOutCtrl.ActFg, minorOutCtrl.OutTime);
                if (JpDebugShow)
                {
                    MyConsole.WriteLine("MINOR 出獎範圍{0}~{1}分", minorOutCtrl.OutMinMin, minorOutCtrl.OutMaxMin);
                    MyConsole.WriteLine("下次出 MINOR 時間 : {0}", minorOutCtrl.OutTime);
                }
            }

            if (majorOutCtrl.ActFg)
            {
                if (jpJudgeDuty == 1 && CheckNoSameJPCommand(JpAward.MAJOR))
                {
                    if (majorOutCtrl.CompareOutTime(dtNow))
                    {
                        if (DBCache.JPSettingData.IsBigWater_MAJOR)
                        {
                            outJp = JpAward.MAJOR;
                            if (JpDebugShow) MyConsole.WriteLine("出JP獎 : MAJOR", Console.ForegroundColor = ConsoleColor.White);
                        }
                        else
                        {
                            majorOutCtrl.ActFg = false;
                            DBCache.SetMajorRealJPOutTimes(majorOutCtrl.ActFg, majorOutCtrl.OutTime);
                            if (JpDebugShow) MyConsole.WriteLine("JP獎 MAJOR 鎖住不出", Console.ForegroundColor = ConsoleColor.White);
                        }
                    }
                }
            }
            else
            {
                majorOutCtrl.SetOutTimeRange(DBCache.JPSettingData.BigWater_MAJOR_DL, DBCache.JPSettingData.BigWater_MAJOR_HL, DBCache.JPSettingData.BigWater_MAJOR_ML,
                                          DBCache.JPSettingData.BigWater_MAJOR_DU, DBCache.JPSettingData.BigWater_MAJOR_HU, DBCache.JPSettingData.BigWater_MAJOR_MU);
                majorOutCtrl.SetNextOutTime();
                DBCache.SetMajorRealJPOutTimes(majorOutCtrl.ActFg, majorOutCtrl.OutTime);
                if (JpDebugShow)
                {
                    MyConsole.WriteLine("MAJOR 出獎範圍{0}~{1}分", majorOutCtrl.OutMinMin, majorOutCtrl.OutMaxMin);
                    MyConsole.WriteLine("下次出 MAJOR 時間 : {0}", majorOutCtrl.OutTime);
                }
            }

            if (megaOutCtrl.ActFg)
            {
                if (jpJudgeDuty == 2 && CheckNoSameJPCommand(JpAward.MEGA))
                {
                    if (megaOutCtrl.CompareOutTime(dtNow))
                    {
                        if (DBCache.JPSettingData.IsBigWater_MEGA)
                        {
                            outJp = JpAward.MEGA;
                            if (JpDebugShow) MyConsole.WriteLine("出JP獎 : MEGA", Console.ForegroundColor = ConsoleColor.White);
                        }
                        else
                        {
                            megaOutCtrl.ActFg = false;
                            DBCache.SetMegaRealJPOutTimes(megaOutCtrl.ActFg, megaOutCtrl.OutTime);
                            if (JpDebugShow) MyConsole.WriteLine("JP獎 MEGA 鎖住不出", Console.ForegroundColor = ConsoleColor.White);
                        }
                    }
                }
            }
            else
            {
                megaOutCtrl.SetOutTimeRange(DBCache.JPSettingData.BigWater_MEGA_DL, DBCache.JPSettingData.BigWater_MEGA_HL, DBCache.JPSettingData.BigWater_MEGA_ML,
                                        DBCache.JPSettingData.BigWater_MEGA_DU, DBCache.JPSettingData.BigWater_MEGA_HU, DBCache.JPSettingData.BigWater_MEGA_MU);
                megaOutCtrl.SetNextOutTime();
                DBCache.SetMegaRealJPOutTimes(megaOutCtrl.ActFg, megaOutCtrl.OutTime);
                if (JpDebugShow)
                {
                    MyConsole.WriteLine("MEGA 出獎範圍{0}~{1}分", megaOutCtrl.OutMinMin, megaOutCtrl.OutMaxMin);
                    MyConsole.WriteLine("下次出 MEGA 時間 : {0}", megaOutCtrl.OutTime);
                }
            }

            if (superOutCtrl.ActFg)
            {
                if (jpJudgeDuty == 3 && CheckNoSameJPCommand(JpAward.SUPER))
                {
                    if (superOutCtrl.CompareOutTime(dtNow))
                    {
                        if (DBCache.JPSettingData.IsBigWater_MEGA)
                        {
                            outJp = JpAward.SUPER;
                            if (JpDebugShow) MyConsole.WriteLine("出JP獎 : SUPER", Console.ForegroundColor = ConsoleColor.White);
                        }
                        else
                        {
                            superOutCtrl.ActFg = false;
                            DBCache.SetSuperRealJPOutTimes(superOutCtrl.ActFg, superOutCtrl.OutTime);
                            if (JpDebugShow) MyConsole.WriteLine("JP獎 SUPER 鎖住不出", Console.ForegroundColor = ConsoleColor.White);
                        }
                    }
                }
            }
            else
            {
                superOutCtrl.SetOutTimeRange(DBCache.JPSettingData.BigWater_SUPER_DL, DBCache.JPSettingData.BigWater_SUPER_HL, DBCache.JPSettingData.BigWater_SUPER_ML,
                                          DBCache.JPSettingData.BigWater_SUPER_DU, DBCache.JPSettingData.BigWater_SUPER_HU, DBCache.JPSettingData.BigWater_SUPER_MU);
                superOutCtrl.SetNextOutTime();
                DBCache.SetSuperRealJPOutTimes(superOutCtrl.ActFg, superOutCtrl.OutTime);
                if (JpDebugShow)
                {
                    MyConsole.WriteLine("SUPER 出獎範圍{0}~{1}分", superOutCtrl.OutMinMin, superOutCtrl.OutMaxMin);
                    MyConsole.WriteLine("下次出 SUPER 時間 : {0}", superOutCtrl.OutTime);
                }
            }


            if (outJp != JpAward.None)
            {
                if (CheckNoSameJPCommand(outJp))
                {
                    //檢查水庫是否足夠
                    double realBank = DBCache.GetJPCountDataJPReal(outJp);
                    double takeMoney = DBCache.GetJPCountDataJPShow(outJp) + 100d;
                    bool fakeOut = false;

                    //水庫不足, 假出歸零彩金
                    if (takeMoney > realBank)
                    {
                        fakeOut = true;
                        if (JpDebugShow) MyConsole.WriteLine("JPAward 機率出牌(" + outJp + ") 水庫不足 假出!!");
                    }
                    else //水庫足, 可真出
                    {
                        if (m_ListenGameServerSocket.AsyncGameServers != null && m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer.Count > 0)
                        {
                            GameServerCode gcode = DBCache.ChooseJPGameServer(outJp, out int playerUid);
                            if (gcode != GameServerCode.None)
                            {
                                //AsyncUserToken temptoken = null;
                                lock (m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
                                {
                                    foreach (AsyncUserToken token in m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
                                    {
                                        if (token.gameType == gcode)
                                        {
                                            bool surplusRegulate = false;  //機率出牌不須校正
                                            bool isAccount = true;       //要入賬(要扣Real水庫)

                                            SetJpCommand(0, 0, 0, outJp, JpLotteryCast.Normal, surplusRegulate, isAccount); //機率出牌沒有LogID, 也不指定機台或玩家.
                                            m_ListenGameServerSocket.SendMessage(token, Message.SerializrToStream(Message.Pack(OperationCode.DBPushJPBonus, outJp, surplusRegulate, isAccount, (int)JpLotteryCast.Normal, 0, playerUid)));
                                            if (JpDebugShow) MyConsole.WriteLine("JPAward 機率出牌(" + outJp + ") 發至(" + token.gameType + " 伺服器) 玩家(" + playerUid + ")");
                                            break;
                                        }
                                    }
                                }
                            }
                            else
                            {
                                fakeOut = true;
                                if (JpDebugShow) MyConsole.WriteLine("JPAward 機率出牌(" + outJp + ") 玩家人數不足 假出!!");
                            }
                        }
                        else
                        {
                            //int delayMinute = 1; //UNDONE: JP出獎延遲1分鐘
                            int delayMinute = 10; //JP出獎延遲10分鐘
                            JpDelayNextOutTime(outJp, delayMinute);
                            if (JpDebugShow) MyConsole.WriteLine("JPAward 機率出牌(" + outJp + ") 沒有遊戲伺服器!! 延遲" + delayMinute + "分鐘");
                        }
                    }

                    if (fakeOut)
                    {
                        RobotPullJPBonus(outJp, JpLotteryCast.Normal);
                        ResetJpOutControl(outJp);
                        //if (JpDebugShow) MyConsole.WriteLine("JPAward 機率出牌(" + outJp + ") 假出!!");
                    }
                }
                else  //相同JP獎正在執行
                {

                }

                checkDelayTimer = (60 / 2);  // Delay 1 Minute
            }
            else
            {
                checkDelayTimer = (10 / 2);  // Delay 10 Second
            }
        }

        static int checkTreasuryDelayTimer = 0;
        static int checkTreasuryStep = 0;
        static int checkTreasuryTimeOutCount = 0;
        static int checkTreasuryWaitCount = 0;
        static int checkTreasuryErrorCount = 0;
        static JpAward TreasuryJp = JpAward.None;
        static bool TreasuryIsAccount = true;

        /// <summary>金庫JP放出計算</summary>
        private static void TreasuryCalculateProc()
        {
            //MARKLU: 金庫JP放出計算
            if (checkTreasuryDelayTimer > 0 && checkTreasuryDelayTimer < 2000)
            {
                checkTreasuryDelayTimer--;
                //UNDONE: 金庫Delay速度 DEBUG DEBUG DEBUG DEBUG DEBUG
                checkTreasuryDelayTimer--;
                checkTreasuryDelayTimer--;
                checkTreasuryDelayTimer--;
                //金庫Delay速度 DEBUG DEBUG DEBUG DEBUG DEBUG DEBUG
                return;
            }

            if (DBCache.JPSettingData.TreasuryFg)
            {
                DateTime dtNow = DateTime.Now;
                if (DBCache.JpRealData.TreasuryActFg == 1)
                {
                    DBCache.JpRealData.TreasuryStatus = 0;
                    TimeSpan interval = DBCache.JpRealData.TreasuryCountdownTime - dtNow;
                    if (interval.TotalMinutes <= 0)
                    {
                        checkTreasuryStep = 0;
                        checkTreasuryTimeOutCount = 0;
                        checkTreasuryErrorCount = 0;
                        DBCache.SetTreasuryActFg(2);
                    }
                    else
                    {
                        checkTreasuryDelayTimer = (60 / 2);  // Delay 1 Minute
                    }
                }
                else if (DBCache.JpRealData.TreasuryActFg == 2)
                {
                    DBCache.JpRealData.TreasuryStatus = 1;
                    TimeSpan interval = DBCache.JpRealData.TreasuryWinTime - dtNow;
                    if (interval.TotalMinutes <= 0)
                    {
                        if (checkTreasuryStep == 0)
                        {
                            checkTreasuryStep = 1;

                            //UNDONE: 選出金庫JP獎
                            TreasuryJp = JpAward.MINOR;

                            //TreasuryIsAccount = true;       //要入賬(要扣Real水庫)
                            TreasuryIsAccount = false;       //UNDONE: DEBUG 金庫JP不入賬(不扣Real水庫)
                        }

                        if (checkTreasuryStep == 1)
                        {
                            if (CheckNoSameJPCommand(TreasuryJp))
                            {
                                checkTreasuryStep = 2;
                                //檢查水庫是否足夠
                                double realBank = DBCache.GetJPCountDataJPReal(TreasuryJp);
                                double takeMoney = DBCache.GetJPCountDataJPShow(TreasuryJp) + 100d;
                                //水庫不足, 假出歸零彩金
                                if ((TreasuryIsAccount && takeMoney > realBank) || checkTreasuryErrorCount > 20 || checkTreasuryTimeOutCount > 5)
                                {
                                    RobotPullJPBonus(TreasuryJp, JpLotteryCast.Treasury);
                                    //ResetJpOutControl(TreasuryJp); //金庫出獎不影響時控JP
                                    DBCache.SetTreasuryActFg(0); //金庫已出, 清除旗號
                                    if (JpDebugShow)
                                    {
                                        if (checkTreasuryErrorCount > 20 || checkTreasuryTimeOutCount > 5)
                                            MyConsole.WriteLine("JPAward 金庫出牌(" + TreasuryJp + ") 找不到玩家-假出!!");
                                        else
                                            MyConsole.WriteLine("JPAward 金庫出牌(" + TreasuryJp + ") 水庫不足-假出!!");
                                    }
                                }
                                else //水庫足, 可真出
                                {
                                    bool sendok = false;

                                    if (m_ListenGameServerSocket.AsyncGameServers != null)
                                    {
                                        Random random = new Random(Guid.NewGuid().GetHashCode());
                                        AsyncUserToken temptoken = null;

                                        lock (m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
                                        {
                                            int serverCount = m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer.Count;

                                            if (serverCount > 0)
                                            {
                                                temptoken = m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer[random.Next(serverCount)];  //選出GameServer
                                            }
                                        }

                                        if (temptoken != null)
                                        {
                                            bool surplusRegulate = false;  //機率出牌不須校正

                                            SetJpCommand(0, 0, 0, TreasuryJp, JpLotteryCast.Treasury, surplusRegulate, TreasuryIsAccount); //機率出牌沒有LogID, 也不指定機台或玩家.
                                            m_ListenGameServerSocket.SendMessage(temptoken, Message.SerializrToStream(Message.Pack(OperationCode.DBPushJPBonus, TreasuryJp, surplusRegulate, TreasuryIsAccount, (int)JpLotteryCast.Treasury, 0, 0)));
                                            checkTreasuryWaitCount = 0;
                                            sendok = true;
                                            if (JpDebugShow) MyConsole.WriteLine("JPAward 金庫出牌(" + TreasuryJp + ") 發至(" + temptoken.gameType + " 伺服器)");
                                        }
                                    }

                                    if (!sendok)
                                    {
                                        checkTreasuryStep = 1; //找不到遊戲伺服器
                                        checkTreasuryErrorCount++;
                                        if (checkTreasuryErrorCount > 2)
                                        {
                                            DBCache.SetTreasuryActFg(0);
                                            if (JpDebugShow) MyConsole.WriteLine("JPAward 金庫出牌(" + TreasuryJp + ") 找不到遊戲伺服器, 取消!!");
                                        }
                                        else
                                        {
                                            DBCache.DelayTreasuryTimers(dtNow);
                                            if (JpDebugShow) MyConsole.WriteLine("JPAward 金庫出牌(" + TreasuryJp + ") 找不到遊戲伺服器(" + checkTreasuryErrorCount + ")!!");
                                        }
                                    }
                                }
                            }
                            else
                            {
                                checkTreasuryDelayTimer = (60 / 2);
                            }
                        }
                        else
                        {
                            checkTreasuryWaitCount++;
                            if (checkTreasuryWaitCount > 10 && CheckNoSameJPCommand(TreasuryJp))
                            {
                                DBCache.SetTreasuryActFg(0); //金庫已出, 清除旗號
                            }
                            checkTreasuryDelayTimer = (60 / 2);
                        }
                    }
                    else
                    {
                        checkTreasuryDelayTimer = (60 / 2);  // Delay 1 Minute
                    }
                }
                else //重新Load金庫Timer
                {
                    DBCache.InitialTreasuryTimers(dtNow);
                    //TreasuryJp = JpAward.None;
                }
            }
            else //金庫功能OFF
            {
                DBCache.SetTreasuryActFg(0);
                checkTreasuryDelayTimer = (300 / 2);  // Delay 5 Minute
            }

            //MyConsole.WriteLine("TreasuryStatus=" + DBCache.JpRealData.TreasuryStatus + ", DlyTmr=" + checkTreasuryDelayTimer);
        }

        /// <summary>儲存玩家遊戲紀錄UID</summary>
        private static void SaveUserGameUidForJPBonus(JpAward jpAward, int userUid, int uguid)
        {
            if (jpCommandList.ContainsKey(jpAward))
            {
                if (jpCommandList[jpAward].Action)
                {
                    jpCommandList.TryGetValue(jpAward, out JPCommand jpComm);
                    if (jpComm.UserUID == 0)
                    {
                        jpComm.UserUID = userUid;
                        jpComm.UgGuid = uguid;
                    }
                    else if (jpComm.UserUID == userUid)
                    {
                        jpComm.UgGuid = uguid;
                    }
                }
            }
        }

        /// <summary>玩家獲取JP彩金</summary>
        private static Dictionary<string, string> PullJPBonus(GameServerCode gameServerCode, Dictionary<string, string> data)
        {
            JpAward jpType = JpAward.None;
            double finalJP = 0;
            bool getAllJp = true;
            if (data.ContainsKey("JpType") && data.ContainsKey("UserID") && data.ContainsKey("UserBet") && data.ContainsKey("UID") && data.ContainsKey("MachUID"))
            {
                jpType = (JpAward)Convert.ToInt32(data["JpType"]);
                int useruid = Convert.ToInt32(data["UserID"]);
                int wLogUid = Convert.ToInt32(data["UID"]);
                int machUid = Convert.ToInt32(data["MachUID"]);
                double userBet = Convert.ToDouble(data["UserBet"]);
                string date = data["DayDate"];
                string payerIP = data["PlayerIP"];
                string sessionId = data["SessionID"];
                JpLotteryCast lotteryCast = (JpLotteryCast)Convert.ToInt32(data["CommandType"]);

                if (JpDebugShow) MyConsole.WriteLine("machUidd=" + machUid + ", " + useruid + ", " + jpType + ", " + lotteryCast + ", " + date);
                //MARKLU: 玩家獲取JP彩金
                if (jpCommandList.ContainsKey(jpType))
                {
                    if (jpCommandList[jpType].Action)
                    {
                        //1.取得最終彩金值
                        //JPCommandType commandType = jpCommandList[jpType].CommandType;
                        finalJP = DBCache.GetJPCountDataJPShow(jpType, userBet, out getAllJp);
                        if (finalJP > 0)
                        {
                            //2.重置彩金
                            if (lotteryCast == JpLotteryCast.Treasury)
                            {
                                DBCache.SetTreasuryActFg(0); //金庫已出, 清除旗號
                            }

                            DBCache.ResetJpShow(jpType); //, finalJP);

                            if (jpCommandList[jpType].IsAccount)
                            {
                                DBCache.DrainOutJpReal(jpType, finalJP);  //要入賬才扣Real水庫的錢
                                if (JpDebugShow) MyConsole.WriteLine("JPAward:" + jpType + "入賬(" + finalJP + ")");
                            }
                            else
                            {
                                if (JpDebugShow) MyConsole.WriteLine("JPAward:" + jpType + "不入帳");
                            }

                            JpLotteryType lotteryType = JpLotteryType.REAL;
                            if (lotteryCast == JpLotteryCast.Normal)
                            {
                                ResetJpOutControl(jpType);  //JP獎定時出獎計時器
                            }

                            //3.複寫log
                            if (wLogUid > 0)
                            {
                                DBCache.EnforceJPUpdateWebLogSuccess(wLogUid, userBet, finalJP, payerIP);
                                lotteryType = JpLotteryType.Enforce; //WEB逼 (有WebLog為後台網頁逼牌)
                            }
                            //4.更新玩家Credit
                            DBCache.UpdateUserBalance(finalJP, useruid, CacheManeger.UpdateBalanceSource.JpBonus);
                            //MARKLU: JP通知LoginServer更新Credit
                            m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer, Message.SerializrToStream(Message.Pack(OperationCode.GetJP, ActorUpdataCode.UpdateCredit, useruid, finalJP, 0)));
                            //5.寫入JP彩金出牌紀錄
                            int jpuid = DBCache.EnforceJPInsertAccountData(gameServerCode, useruid, jpType, finalJP, payerIP, sessionId, lotteryType, lotteryCast);
                            //6.更新玩家遊戲紀錄
                            if (jpCommandList[jpType].UserUID == useruid)
                            {
                                DBCache.UpdateUserGamedataForJpBonus(jpCommandList[jpType].UgGuid, finalJP, jpuid);
                                DBCache.UpdateUserSessionAccount(useruid, Convert.ToInt32(sessionId), payerIP, 0d, 0d, finalJP);
                                //if (JpDebugShow) Console.WriteLine("更新玩家(" + useruid + ")遊戲紀錄[Guid:" + jpCommandList[jpType].UgGuid + ", JP:" + finalJP + "], 日期:" + date);//MARKLU:更新玩家遊戲紀錄
                            }
                            //7.重置JP命令
                            ResetJpCommand(jpType);
                            //8.更新機台總帳&日帳
                            DBCache.UpdateGameAccountTableForJP(gameServerCode, jpType, userBet, finalJP, machUid, date);
                            //9.重置玩家押分排行資訊
                            DBCache.ResetRankRecordTable(useruid, finalJP);
                            //10.廣播中JP彩金
                            BroadcastJPWinner(gameServerCode, useruid, jpType, finalJP);
                            //11.更新玩家遊戲報告
                            DBCache.UpdateReportGameDataJP(gameServerCode, useruid, finalJP, date);
                        }
                    }
                }
            }

            //4.製作回傳給GameServer的Info
            Dictionary<string, string> info = new Dictionary<string, string>();
            info.Add("JpType", data["JpType"]);
            info.Add("UserID", data["UserID"]);
            info.Add("FinalJP", finalJP.ToString());
            info.Add("GetAllJP", getAllJp.ToString());
            return info;
        }

        /// <summary>機器人假出JP彩金</summary>
        private static void RobotPullJPBonus(JpAward jpType, JpLotteryCast lotteryCast)
        {
            //MARKLU: 機器人假出JP彩金
            //1.選出機器人身份 & 設定機台
            DBCache.RandomChooseBot(out int useruid, out int machUid);
            machUid = 0; //2022/08/03 修改為"機台全部任選"

            string payerIP = "0.0.0.0";
            string sessionId = "0";

            //2.取得要出的彩金值
            Random random = new Random(Guid.NewGuid().GetHashCode());

            double tbet = DBCache.JPSettingData.AllJPGetMinBet;
            if (random.Next(1000) < 250)
            {
                tbet = DBCache.JPSettingData.HalfJPGetMinBet; //拉一半
            }
            else
            {
                if (DBCache.JPSettingData.FJP_Level > 1)
                {
                    for (int i = 0; i < DBCache.JPSettingData.FJP_Level; i++)
                    {
                        tbet += DBCache.JPSettingData.AllJPGetMinBet;
                        if (random.Next(1000) < 500) break;
                    }
                }
            }
            double finalJP = DBCache.GetJPCountDataJPShow(jpType, tbet, out bool getAllJp);

            //3.重置彩金
            DBCache.ResetJpShow(jpType); //, finalJP);

            if (useruid > 0)
            {
                GameServerCode gServerCode = GameServerCode.XiyouGame;
                if (machUid == 0)
                {
                    int servercnt = m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer.Count;
                    if (servercnt > 0)
                    {
                        int svoIdx = random.Next(servercnt);
                        for (int i = 0; i < servercnt; i++)
                        {
                            gServerCode = m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer[svoIdx].gameType;
                            GameTypeCode gtype = DBCache.GameServerCodeToGameTypeCode(gServerCode);
                            if (gtype == GameTypeCode.Arcade || gtype == GameTypeCode.Poker)
                            {
                                if (random.Next(1000) < 300)  // 押分機,撲克 縮減7/10
                                {
                                    break;
                                }
                            }
                            else
                            {
                                break;
                            }
                            svoIdx++;
                            if (svoIdx >= servercnt) svoIdx = 0;
                        }
                    }
                    else
                    {
                        //gServerCode = GameServerCode.XiyouGame;  //若沒有遊戲, 通設為齊天大聖
                        return;  //若沒有遊戲, 不做彩金出牌紀錄
                    }
                }
                else
                {
                    gServerCode = DBCache.GetDBMachineGameServerCode(machUid);
                }

                //4.寫入JP彩金出牌紀錄
                DBCache.EnforceJPInsertAccountData(gServerCode, useruid, jpType, finalJP, payerIP, sessionId, JpLotteryType.FAKE, lotteryCast); //機器人假出

                //5.廣播中JP彩金
                BroadcastJPWinner(gServerCode, useruid, jpType, finalJP);
            }
        }
        /// <summary>廣播中JP彩金</summary>
        private static void BroadcastJPWinner(GameServerCode gameServerCode, int useruid, JpAward jpType, double finalJP)
        {
            string Nickname = "";

            bool besend = false;

            lock (DBCache.UserDataList)
            {
                if (DBCache.UserDataList.ContainsKey(useruid))
                {
                    Nickname = DBCache.UserDataList[useruid].Nickname;

                    besend = true;
                }
            }

            if (besend == true)
            {
                Dictionary<string, SystemTextColor> text = new Dictionary<string, SystemTextColor>();
                //info.UserID  info.Nickname
                string uname = MaskUserName(Nickname);
                //string game = DBCache.GetDBMachineGameServerCode(machUid);
                DBCache.GetGameServerName(gameServerCode, out string gameName, out string egameName);

                //string currency = DBCache.GetCurrencyString(finalJP);
                string currency = DBCache.HistoryConvertRatioForText(finalJP);
                string msg = string.Format("JP大赢家! 恭喜玩家 {0} 在 {1} 中 {2} JP {3}", uname, gameName, jpType, currency);
                string emsg = string.Format("JP Winner! Player {0} Hit {1} JP {2} on {3}", uname, jpType, currency, egameName);

                //Console.WriteLine(msg);
                //MARKLU:廣播中JP彩金 
                SystemTextColor color;
                if (jpType == JpAward.SUPER) color = SystemTextColor.Gold;
                else if (jpType == JpAward.MEGA) color = SystemTextColor.Green;
                else if (jpType == JpAward.MAJOR) color = SystemTextColor.Skyblue;
                else color = SystemTextColor.Red;

                text.Add(msg, color);
                text.Add(emsg, color);
                BroadCastMessage(text);
            }
        }

        public static string MaskUserName(string userName)
        {
            if (userName.Length >= 5)
            {
                string hdname = userName.Substring(0, 2);
                string tlname = userName.Substring(userName.Length - 2, 2);

                for (int i = 0; i < userName.Length - 4; i++)
                {
                    hdname = hdname + "*";
                }

                return (hdname + tlname);
            }
            else if (userName.Length == 4)
            {
                string hdname = userName.Substring(0, 2);
                string tlname = userName.Substring(userName.Length - 1, 1);
                return (hdname + "*" + tlname);
            }
            else if (userName.Length == 3)
            {
                string hdname = userName.Substring(0, 1);
                string tlname = userName.Substring(userName.Length - 1, 1);
                return (hdname + "*" + tlname);
            }
            else if (userName.Length == 2)
            {
                return (userName.Substring(0, 1) + "*");
            }
            return userName;
        }

        /// <summary>監看JP獎動作旗號</summary>
        private static void JPActionTimerWatchDog()
        {
            //MARKLU: JP獎動作WatchDog
            //int countMax = (120 / 2);  //UNDONE: 120秒逾時 (Server端TimeOut設定為360秒)
            int countMax = (600 / 2);  //600秒逾時 (Server端TimeOut設定為360秒)

            foreach (KeyValuePair<JpAward, JPCommand> comm in jpCommandList)
            {
                if (comm.Value.Action)
                {
                    comm.Value.PassTimes++;
                    if (comm.Value.PassTimes > countMax)
                    {
                        comm.Value.Action = false;  //逾時關閉JP命令
                        if (comm.Value.LogID > 0)
                        {
                            DBCache.EnforceJPUpdateWebLogFail(comm.Value.LogID);
                            if (JpDebugShow) MyConsole.WriteLine("JP命令(WEB逼牌)(" + comm.Value.LogID + ")[" + comm.Key + "]逾時取消!!");
                        }
                        else
                        {
                            if (comm.Value.LotteryCast == JpLotteryCast.Treasury)
                            {
                                checkTreasuryStep = 1; //逾時取消
                                checkTreasuryTimeOutCount++;
                                if (JpDebugShow) MyConsole.WriteLine("JP命令(金庫出牌)[" + comm.Key + "]逾時取消!!");
                            }
                            else
                            {
                                if (JpDebugShow) MyConsole.WriteLine("JP命令(機率出牌)[" + comm.Key + "]逾時取消!!");
                            }
                        }

                    }
                }
            }
        }

        /// <summary>確認沒有相同JP獎正在執行</summary>
        private static bool CheckNoSameJPCommand(JpAward jpType)
        {
            if (jpCommandList.ContainsKey(jpType))
            {
                if (jpCommandList[jpType].Action)
                {
                    return false;  //相同JP獎正在動作中
                }
                return true;
            }
            return false;  //JP獎錯誤
        }

        /// <summary>清除JP獎動作(以JpType)</summary>
        private static void ResetJpCommand(JpAward jpType)
        {
            if (jpCommandList.ContainsKey(jpType))
            {
                jpCommandList[jpType].Action = false;
            }
        }
        /// <summary>清除JP獎動作(以LogID)</summary>
        private static void ResetJpCommand(int logID)
        {
            foreach (JPCommand comm in jpCommandList.Values)
            {
                if (comm.LogID == logID)
                {
                    comm.Action = false;
                    break;
                }
            }
        }
        /// <summary>設定JP獎動作</summary>
        private static void SetJpCommand(int logID, int machUID, int userUID, JpAward jpType, JpLotteryCast lotteryCast, bool surplusRegulate, bool isAccount)
        {
            if (jpCommandList.ContainsKey(jpType))
            {
                jpCommandList[jpType].Action = true;
                jpCommandList[jpType].LogID = logID;
                jpCommandList[jpType].MachineUID = machUID;
                jpCommandList[jpType].UserUID = userUID;
                jpCommandList[jpType].SurplusRegulate = surplusRegulate;
                jpCommandList[jpType].IsAccount = isAccount;
                jpCommandList[jpType].LotteryCast = lotteryCast;
                jpCommandList[jpType].PassTimes = 0;
            }
        }
        /// <summary></summary>
        private static void InitialJpCommand()
        {
            jpCommandList = new Dictionary<JpAward, JPCommand>();
            jpCommandList.Add(JpAward.MINOR, new JPCommand());
            jpCommandList.Add(JpAward.MAJOR, new JPCommand());
            jpCommandList.Add(JpAward.MEGA, new JPCommand());
            jpCommandList.Add(JpAward.SUPER, new JPCommand());
        }

        private static Dictionary<JpAward, JPCommand> jpCommandList;  //4種JP同時間只能各有1個

        public class JPCommand
        {
            public bool Action = false;
            public int LogID = 0;      //0=機率出牌, Other=Web逼牌
            public int MachineUID = 0;
            public int UserUID = 0;
            public bool SurplusRegulate;
            public bool IsAccount;
            /// <summary>玩家遊戲紀錄UID</summary>
            public int UgGuid = 0;
            public JpLotteryCast LotteryCast = JpLotteryCast.Normal;
            public int PassTimes = 0;   //逾時Timer
        }

        public class JPOutControl
        {
            public bool ActFg = false;
            public DateTime OutTime;
            public int OutMinMin;
            public int OutMaxMin;
            public int PushTimes;

            /// <summary>設定JP出獎時間範圍</summary>
            public void SetOutTimeRange(int minDay, int minHour, int minMinute, int maxDay, int maxHour, int maxMinute)
            {
                OutMinMin = (minDay * 24 * 60) + (minHour * 60) + minMinute;
                OutMaxMin = (maxDay * 24 * 60) + (maxHour * 60) + maxMinute;
                //if (JpDebugShow) MyConsole.WriteLine("JP出獎時間" + OutMinMin + "~" + OutMaxMin);
            }
            /// <summary>設定下一次JP出獎時間</summary>
            public void SetNextOutTime()
            {
                Random rand = new Random(Guid.NewGuid().GetHashCode());
                //int addtimes = rand.Next(OutMinMin, OutMaxMin);
                //OutTime = DateTime.Now.AddMinutes(addtimes);
                int addtimes = (rand.Next(OutMinMin, OutMaxMin) * 60) + rand.Next(60);
                OutTime = DateTime.Now.AddSeconds(addtimes);
                PushTimes = 0;
                ActFg = true;
            }
            /// <summary>延遲下一次JP出獎時間</summary>
            public void DelayNextOutTime(int delayMinute)
            {
                OutTime = DateTime.Now.AddMinutes(delayMinute); //以現在時間為準來延遲
            }
            /// <summary>判斷JP出獎時間是否到了</summary>
            public bool CompareOutTime(DateTime dtNow)
            {
                TimeSpan interval = OutTime - dtNow;
                if (interval.TotalMinutes <= 0)
                {
                    if (PushTimes < 10)
                    {
                        PushTimes++;
                        return true;
                    }
                    else
                    {
                        PushTimes = 0;
                        OutTime = DateTime.Now.AddMinutes(30);  //發10次都沒有成功, 延遲30分鐘後再發
                    }
                }
                return false;
            }
        }

        /// <summary>MINOR獎定時出獎計時器</summary>
        static JPOutControl minorOutCtrl = new JPOutControl();
        /// <summary>MAJOR獎定時出獎計時器</summary>
        static JPOutControl majorOutCtrl = new JPOutControl();
        /// <summary>MEGA獎定時出獎計時器</summary>
        static JPOutControl megaOutCtrl = new JPOutControl();
        /// <summary>SUPER獎定時出獎計時器</summary>
        static JPOutControl superOutCtrl = new JPOutControl();

        /// <summary>重置JP獎定時出獎計時器</summary>
        private static void ResetJpOutControl(JpAward jpType)
        {
            if (jpType == JpAward.MINOR)
            {
                minorOutCtrl.ActFg = false;
                DBCache.SetMinorRealJPOutTimes(minorOutCtrl.ActFg, minorOutCtrl.OutTime);
            }
            else if (jpType == JpAward.MAJOR)
            {
                majorOutCtrl.ActFg = false;
                DBCache.SetMajorRealJPOutTimes(majorOutCtrl.ActFg, majorOutCtrl.OutTime);
            }
            else if (jpType == JpAward.MEGA)
            {
                megaOutCtrl.ActFg = false;
                DBCache.SetMegaRealJPOutTimes(megaOutCtrl.ActFg, megaOutCtrl.OutTime);
            }
            else if (jpType == JpAward.SUPER)
            {
                superOutCtrl.ActFg = false;
                DBCache.SetSuperRealJPOutTimes(superOutCtrl.ActFg, superOutCtrl.OutTime);
            }
        }
        /// <summary>延遲下一次JP出獎時間</summary>
        private static void JpDelayNextOutTime(JpAward jpType, int minute)
        {
            if (jpType == JpAward.MINOR) minorOutCtrl.DelayNextOutTime(minute);
            else if (jpType == JpAward.MAJOR) majorOutCtrl.DelayNextOutTime(minute);
            else if (jpType == JpAward.MEGA) megaOutCtrl.DelayNextOutTime(minute);
            else if (jpType == JpAward.SUPER) superOutCtrl.DelayNextOutTime(minute);
        }

