        #region 廣播系統維護公告訊息
        private static DateTime checkTime;
        private static int ServiceNotiStat = 0;
        private static int ServiceNotiStatDelayTimer = 0;

        /// <summary>廣播系統維護公告訊息</summary>
        private static void SystemServiceTimeCheck()
        {
            ServiceNotiStatDelayTimer++;
            if (ServiceNotiStatDelayTimer < 30) return; //每1分鐘判一次即可(此線程每2秒呼叫一次)
            ServiceNotiStatDelayTimer = 0;

            DateTime now = DateTime.Now;

            if (ServiceNotiStat == 0)
            {
                DBCache.SetServiceNotiTimeCheck();
                ServiceNotiStat = 1;
                //MyConsole.WriteLine("廣播系統維護訊息 : Initial");
            }
            else if (ServiceNotiStat == 1)
            {
                if (DBCache.CompareServiceAdvanceTime(now) <= 0)
                {
                    if (DBCache.CompareServiceTime(now) > 0)
                    {
                        checkTime = DateTime.Now;
                        ServiceNotiStat = 2;
                        //MyConsole.WriteLine("廣播系統維護訊息 : 預報時間到");
                    }
                    else
                    {
                        ServiceNotiStat = 3;
                        //MyConsole.WriteLine("廣播系統維護訊息 : 逾時");
                    }
                }
                //}
            }
            else if (ServiceNotiStat == 2)
            {
                if (DBCache.CompareServiceTime(now) <= 0)
                {
                    BroadCastServiceMessage(1, DBCache.GetServiceNotificationMessage()); //發最後一次訊息
                    ServiceNotiStat = 3;
                    //MyConsole.WriteLine("廣播系統維護訊息 : 維護時間到");
                }
                else
                {
                    //開始預報
                    int tdiff = checkTime.CompareTo(now);
                    if (tdiff < 0)
                    {
                        checkTime = now.AddSeconds(120); //每2分鐘發一次訊息
                        BroadCastServiceMessage(0, DBCache.GetServiceNotificationMessage());
                        //MyConsole.WriteLine("廣播系統維護訊息 : 預報中");
                    }
                }
            }
            else if (ServiceNotiStat == 3)
            {
                DBCache.SetServiceNotiTimeNext();
                ServiceNotiStat = 0;
                //MyConsole.WriteLine("廣播系統維護訊息 : 重設");
            }
            else
            {
                ServiceNotiStat = 0;
            }
        }

