        /// <summary>
        /// 檢查連線
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private static void CheckListen(object sender)
        {
            while (true)
            {
                if (m_ListenLoginSocket.LoginServer.Socket != null)
                {
                    if (m_ListenLoginSocket.LoginServer.NoCheckTime >= 6)
                    {
                        //踢掉
                        m_ListenLoginSocket.CloseClient(m_ListenLoginSocket.LoginServer);
                    }
                    else
                    {
                        if (!m_ListenLoginSocket.LoginServer.IsAlive)
                        {
                            m_ListenLoginSocket.LoginServer.NoCheckTime++;
                            if (m_ListenLoginSocket.LoginServer.NoCheckTime > 2)
                            {
                                MyConsole.WriteLine(string.Format("LoginServer未回應,警告{0}次", m_ListenLoginSocket.LoginServer.NoCheckTime), Console.ForegroundColor = ConsoleColor.Red);
                            }
                        }
                        else
                            m_ListenLoginSocket.AsyncLoginServer.ConnectedLoginServer.IsAlive = false;
                    }
                }

                lock (m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
                {
                    if (m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer.Count > 0)
                    {
                        List<AsyncUserToken> NoCheckGameServer = new List<AsyncUserToken>();

                        foreach (var tempGame in m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
                        {
                            if (tempGame.NoCheckTime >= 6)
                            {
                                NoCheckGameServer.Add(tempGame);

                                
                            }
                            else
                            {
                                if (!tempGame.IsAlive)
                                {
                                    tempGame.NoCheckTime++;
                                    if (tempGame.NoCheckTime > 2)
                                    {
                                        MyConsole.WriteLine(string.Format("GameServer:{0}[{1}]未回應,警告{2}次", tempGame.gameType.ToString(), tempGame.Socket.LocalEndPoint, tempGame.NoCheckTime), Console.ForegroundColor = ConsoleColor.Red);
                                    }
                                }
                                else
                                    tempGame.IsAlive = false;
                            }
                        }

                        if (NoCheckGameServer.Count > 0)
                        {
                            for (int i = 0; i < NoCheckGameServer.Count; i++)
                            {
                                //踢掉
                                m_ListenGameServerSocket.CloseClient(NoCheckGameServer[i]);
                            }
                        }
                    }
                }

                Thread.Sleep(10000);
            }
        }

        /// <summary>
        /// 傳送心跳
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private static void SendHeartBeat(object sender)
        {
            while (true)
            {
                try
                {
                    //傳心跳確認給LoginServer
                    if (m_ListenLoginSocket.LoginServer.Socket != null)
                    {
                        m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.LoginServer, Message.SerializrToStream(Message.PackHeartBeatData(OperationCode.HeartBeat,40257)));

                        //Console.WriteLine(string.Format("傳送心跳給LoginServer", Console.ForegroundColor = ConsoleColor.Green));
                    }

                    lock (m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
                    {
                        //傳心跳確認給GameServer
                        if (m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer.Count > 0)
                        {
                            foreach (var tempGame in m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
                            {
                                try
                                {
                                    if (tempGame == null || tempGame.Socket == null)
                                    {
                                        MyConsole.WriteLine(tempGame.gameType.ToString());

                                        m_ListenGameServerSocket.CloseClient(tempGame);
                                    }
                                    else
                                    {
                                        m_ListenGameServerSocket.SendMessage(tempGame, Message.SerializrToStream(Message.PackHeartBeatData(OperationCode.HeartBeat,40257)));
                                    }
                                }
                                catch (Exception k)
                                {
                                    MyConsole.WriteLine(k.Message);
                                    MyConsole.WriteLine(k.StackTrace);
                                }

                            }
                            //Console.WriteLine(string.Format("傳送心跳給GameServer", Console.ForegroundColor = ConsoleColor.Green));
                        }
                    }
                }
                catch (Exception e)
                {
                    MyConsole.WriteLine(e.Message, Console.ForegroundColor = ConsoleColor.Red);
                    MyConsole.WriteLine(e.StackTrace);
                }

                Thread.Sleep(5000);
            }

        }

