        #region H5外部錢包取回
        /// <summary>除錯訊息旗號</summary>
        static bool PGSDbFg = false; //_UNDONE: 外部錢包取回 DEBUG

        const int PGST1Sec = 20;//Loop 20 = 1秒

        /// <summary>重設LobbySession</summary>
        static void ResetLobbySession(UserData userData)
        {
            if (userData.Wallet >= Walletlocation.PGS)
            {
                DBCache.SetLobbySession(userData.UserUID, userData.Wallet);
            }
        }

        /// <summary>WebApi H5取回錢包</summary>
        static void GetAccountBalanceForMerchant(AsyncUserToken token, GameData request)
        {
            try
            {
                if (request.webInfo?.CalculateInfo == null || request.webInfo.CalculateInfo.Count < 3 ||
                    !Int32.TryParse(request.webInfo.CalculateInfo[2], out int entityId))
                {
                    SendMerchantBalanceResponse(token, request, ErrorCode.CustomError, "InvalidRequest");
                    return;
                }

                string playerId = request.webInfo.CalculateInfo[0];
                string agentId = request.webInfo.CalculateInfo[1];
                bool merchantValid = myAcess.ExecuteInReadCommitted(connection =>
                {
                    using (var command = new MySqlCommand(
                        "SELECT COUNT(*) FROM H5AgentTable h INNER JOIN Entity e ON e.id = h.id " +
                        "WHERE h.id = @entityId AND h.AgentId = @agentId AND h.Enabled = 1 AND e.Name = h.AgentId",
                        connection))
                    {
                        command.CommandTimeout = 15;
                        command.Parameters.AddWithValue("@entityId", entityId);
                        command.Parameters.AddWithValue("@agentId", agentId);
                        return Convert.ToInt32(command.ExecuteScalar()) == 1;
                    }
                });
                if (!merchantValid)
                {
                    SendMerchantBalanceResponse(token, request, ErrorCode.CustomError, "MerchantScopeMismatch");
                    return;
                }

                int userUid = DBCache.GetuserUID(playerId);
                UserData user = userUid > 0 ? DBCache.Getuser(userUid) : null;
                if (user == null || user.EntityId != entityId)
                {
                    SendMerchantBalanceResponse(token, request, ErrorCode.CustomError, "PlayerNotFound");
                    return;
                }

                if (!RecallExternalWalletForMerchantApi(userUid))
                {
                    SendMerchantBalanceResponse(token, request, ErrorCode.CustomError, "ExternalWalletRecallFailed");
                    return;
                }

                user = DBCache.Getuser(userUid);
                string balance = Convert.ToDecimal(user.UserBalance).ToString("F4", CultureInfo.InvariantCulture);
                SendMerchantBalanceResponse(token, request, ErrorCode.Ok, balance);
            }
            catch (Exception exception)
            {
                MyConsole.WriteLine($"GetAccountBalance failed: {exception.Message}");
                SendMerchantBalanceResponse(token, request, ErrorCode.CustomError, "BusinessError");
            }
        }

        static PlayerKickPlayerSnapshot GetPlayerKickSnapshot(int userUid)
        {
            UserData user = DBCache.Getuser(userUid);
            return user == null
                ? null
                : new PlayerKickPlayerSnapshot(user.UserUID, user.EntityId, user.UserID, user.Usersituation);
        }

        /// <summary>
        /// MQ 踢人使用嚴格單一路由：在 Login 就只通知 Login；在遊戲就只通知權威 GameServer。
        /// GameServer 完成清理後沿既有 QuitServer 鏈通知 Login，再由 Login 將 Usersituation 更新為 0。
        /// </summary>
        static bool DispatchPlayerKick(PlayerKickCommandV1 command)
        {
            UserData user = DBCache.Getuser(command.UserUID);
            if (user == null || user.Usersituation == 0) return true;

            byte[] message = Message.SerializrToStream(Message.Pack(OperationCode.QuitServer, command.UserUID));
            if (user.Usersituation == 1)
            {
                if (m_ListenLoginSocket.LoginServer == null) return false;
                m_ListenLoginSocket.SendMessage(m_ListenLoginSocket.LoginServer, message);
                return true;
            }

            GameServerCode target = (GameServerCode)user.Usersituation;
            lock (m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
            {
                foreach (AsyncUserToken gameToken in m_ListenGameServerSocket.AsyncGameServers.ConnectedGameServer)
                {
                    if (gameToken.gameType != target) continue;
                    m_ListenGameServerSocket.SendMessage(gameToken, message);
                    return true;
                }
            }

            return false;
        }

        static void SendMerchantBalanceResponse(AsyncUserToken token, GameData response, ErrorCode errorCode,
            string value)
        {
            response.errorCode = errorCode;
            response.webInfo.CalculateInfo = new List<string> { value };
            m_ListenWebServerSocket.SendMessage(token, Message.SerializrToStream(response));
        }

        static bool RecallExternalWalletForMerchantApi(int userUid)
        {
            UserData userData = DBCache.Getuser(userUid);
            if (userData == null)
            {
                BatchDepositV2OperationalLog.Write("error", "wallet_recall", "player_not_found", new
                {
                    UserUID = userUid,
                    Result = "ExternalWalletRecallFailed"
                });
                return false;
            }

            if (!CheckExtWallet(userData))
            {
                BatchDepositV2OperationalLog.Write("info", "wallet_recall", "not_required", new
                {
                    UserUID = userUid,
                    Result = "Succeeded"
                });
                return true;
            }

            BatchDepositV2OperationalLog.Write("info", "wallet_recall", "started", new
            {
                UserUID = userUid
            });

            ResetLobbySession(userData);
            var work = new PGSlotTransTask(userUid, userData);
            int errorCount = PGSTransTaskProc2(work);
            if (errorCount == 0)
            {
                BatchDepositV2OperationalLog.Write("info", "wallet_recall", "completed", new
                {
                    UserUID = userUid,
                    ErrorCount = errorCount,
                    Result = "Succeeded"
                });
                return true;
            }

            BatchDepositV2OperationalLog.Write("error", "wallet_recall", "failed", new
            {
                UserUID = userUid,
                ErrorCount = errorCount,
                Result = "ExternalWalletRecallFailed"
            });
            MyConsole.WriteLine($"Merchant API external wallet recall failed. UserUID={userUid}");
            return false;
        }

        /// <summary>WebApi H5取回錢包</summary>
        static void CheckPlayerBalanceWithH5(AsyncUserToken token, GameData RicevieData)
        {
            int UserUID = Int32.Parse(RicevieData.webInfo.CalculateInfo[0]);

            UserData userData = DBCache.Getuser(UserUID);

            if (userData == null)
            {
                MyConsole.WriteLine($"CheckPlayerBalanceWithH5 : 找不到玩家Uid[{UserUID}]");
            }
            else
            {
                bool donefg = true;
                if (CheckExtWallet(userData))
                {
                    ResetLobbySession(userData); //重設LobbySession, 讓原本網頁大廳的Session失效

                    PGSlotTransTask work = new PGSlotTransTask(UserUID, userData);

                    int errCnt = PGSTransTaskProc2(work);

                    if (errCnt == 0)
                    {
                        //MyConsole.WriteLine($"CheckPlayerBalanceWithH5 : 玩家[{userData.UserID}]H5錢包已取回");
                    }
                    else
                    {
                        donefg = false;
                        MyConsole.WriteLine($"CheckPlayerBalanceWithH5 : 玩家[{userData.UserID}]H5錢包取回失敗");
                    }
                }
                else
                {
                    //MyConsole.WriteLine($"CheckPlayerBalanceWithH5 : 玩家[{userData.UserID}]H5錢包不須取回");
                }

                //執行結果正確
                if (donefg)
                {
                    //double bs = Math.Floor(userData.UserBalance * 1000) / 1000;  //"玩家UID(或ID),(H5回收後玩家的餘額，要字串小數點後3位)";
                    string balance = userData.UserBalance.ToString();
                    RicevieData.webInfo.CalculateInfo[0] = $"{UserUID},{balance}";
                    RicevieData.errorCode = ErrorCode.Ok;
                    m_ListenWebAPIServerSocket.SendMessage(token, Message.SerializrToStream(RicevieData));
                }
            }

            RicevieData.errorCode = ErrorCode.CustomError;
            m_ListenWebAPIServerSocket.SendMessage(token, Message.SerializrToStream(RicevieData));
        }

        static bool CheckExtWallet(UserData userData)
        {
            //UserData userData = DBCache.Getuser(playerUid);
            //if (userData == null)
            //{
            //    if (PGSDbFg) MyConsole.WriteLine($"X:PGSChkTransTask  找不到玩家[{playerUid}]");
            //    return false;
            //}

            if (CountrySettingData.ExternGameEnableFg == false)
            {
                userData.Wallet = Walletlocation.LOCAL;
                //if (PGSDbFg) MyConsole.WriteLine($"U:玩家[{userData.UserID}] 外部遊戲未啟用");
