        /// <summary>執行取回工作</summary>
        static int PGSTransTaskProc2(PGSlotTransTask work)
        {
            UserData userData = work.UserData;
            int errCnt = 0;

            while (true)
            {
                Walletlocation doWallet = Walletlocation.none;
                bool allDone = true;

                if (work.WallGetList.Count > 0)
                {
                    //if (userData.PGS_Ret)
                    if (allDone && work.WallGetList.Contains(Walletlocation.PGS))
                    {
                        GPTransResult chkres = DBCache.PGSTransferOutPlayerBalance(work);

                        if (chkres == GPTransResult.未完成)
                        {
                            doWallet = Walletlocation.PGS;
                            allDone = false;
                        }
                        else
                        {
                            work.GetWalletDone(Walletlocation.PGS);
                            userData.PGS_Ret = false; //設為已取回
                        }

                        if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] PGS取回[{chkres}]");
                    }

                    //if (userData.JILI_Ret && allDone)
                    if (allDone && work.WallGetList.Contains(Walletlocation.JILI))
                    {
                        GPTransResult chkres = DBCache.JILITransferOutPlayerBalance(work);

                        if (chkres == GPTransResult.未完成)
                        {
                            doWallet = Walletlocation.JILI;
                            allDone = false;
                        }
                        else
                        {
                            work.GetWalletDone(Walletlocation.JILI);
                            userData.JILI_Ret = false; //設為已取回
                        }

                        if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] JILI取回[{chkres}]");
                    }

                    //if (userData.FC_Ret && allDone)
                    if (allDone && work.WallGetList.Contains(Walletlocation.FC))
                    {
                        GPTransResult chkres = DBCache.FCTransferOutPlayerBalance(work);

                        if (chkres == GPTransResult.未完成)
                        {
                            doWallet = Walletlocation.FC;
                            allDone = false;
                        }
                        else
                        {
                            work.GetWalletDone(Walletlocation.FC);
                            userData.FC_Ret = false; //設為已取回
                        }

                        if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] FC取回[{chkres}]");
                    }

                    //if (userData.AceWin_Ret && allDone)
                    if (allDone && work.WallGetList.Contains(Walletlocation.AceWin))
                    {
                        GPTransResult chkres = DBCache.AceWinTransferOutPlayerBalance(work);

                        if (chkres == GPTransResult.未完成)
                        {
                            doWallet = Walletlocation.AceWin;
                            allDone = false;

                            _ = AceWin.KickMember(userData.UserID);
                        }
                        else
                        {
                            work.GetWalletDone(Walletlocation.AceWin);
                            work.LocalTransId = null;
                            userData.AceWin_Ret = false; //設為已取回
                        }

                        if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] AceWin取回[{chkres}]");
                    }

                    //if (userData.JDB_Ret && allDone)
                    if (allDone && work.WallGetList.Contains(Walletlocation.JDB))
                    {
                        GPTransResult chkres = DBCache.JDBTransferOutPlayerBalance(work);

                        if (chkres == GPTransResult.未完成)
                        {
                            doWallet = Walletlocation.JDB;
                            allDone = false;

                            _ = JDB.KickMember(userData.UserID);
                        }
                        else
                        {
                            work.GetWalletDone(Walletlocation.JDB);
                            userData.JDB_Ret = false; //設為已取回
                        }

                        if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] JDB取回[{chkres}]");
                    }

                    //if (userData.DCT_Ret && allDone)
                    if (allDone && work.WallGetList.Contains(Walletlocation.DCT))
                    {
                        GPTransResult chkres = DBCache.DCTTransferOutPlayerBalance(work);

                        if (chkres == GPTransResult.未完成)
                        {
                            doWallet = Walletlocation.DCT;
                            allDone = false;

                            _ = DCT.KickMember(userData.UserID);
                        }
                        else
                        {
                            work.GetWalletDone(Walletlocation.DCT);
                            userData.DCT_Ret = false; //設為已取回
                        }

                        if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] DCT取回[{chkres}]");
                    }

                    if (allDone && work.WallGetList.Contains(Walletlocation.HABA))
                    {
                        _ = HABA.KickMember(userData.UserID, userData.UserID); //HABA取回時, 一律將玩家登出, 讓GameUrl無效

                        GPTransResult chkres = DBCache.HABATransferOutPlayerBalance(work);

                        if (chkres == GPTransResult.未完成)
                        {
                            doWallet = Walletlocation.HABA;
                            allDone = false;

                            //_ = HABA.UpdatePlayerPassword(userData.UserID, userData.UserID); //HABA取回失敗時, 試著將密碼修正看看
                        }
                        else
                        {
                            work.GetWalletDone(Walletlocation.HABA);
                            userData.HABA_Ret = false; //設為已取回
                        }

                        if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] HABA取回[{chkres}]");
                    }

                    if (allDone && work.WallGetList.Contains(Walletlocation.FastSpin))
                    {
                        GPTransResult chkres = DBCache.FastSpinTransferOutPlayerBalance(work);

                        if (chkres == GPTransResult.未完成)
                        {
                            doWallet = Walletlocation.FastSpin;
                            allDone = false;

                            _ = FastSpin.KickMember(userData.UserID);
                        }
                        else
                        {
                            work.GetWalletDone(Walletlocation.FastSpin);
                            userData.FastSpin_Ret = false; //設為已取回
                        }

                        if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] FastSpin取回[{chkres}]");
                    }

                    if (allDone && work.WallGetList.Contains(Walletlocation.Spade))
                    {
                        GPTransResult chkres = DBCache.SpadeTransferOutPlayerBalance(work);

                        if (chkres == GPTransResult.未完成)
                        {
                            doWallet = Walletlocation.Spade;
                            allDone = false;

                            _ = Spade.KickMember(userData.UserID);
                        }
                        else
                        {
                            work.GetWalletDone(Walletlocation.Spade);
                            userData.Spade_Ret = false; //設為已取回
                        }

                        if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] Spade取回[{chkres}]");
                    }

                    if (allDone && work.WallGetList.Contains(Walletlocation.PlayTech))
                    {
                        var kres = PlayTech.KickMember(userData.UserID);

                        if (kres.Result.ErrorCode == "0" || kres.Result.ErrorCode == "5")
                        {
                            GPTransResult chkres = DBCache.PlayTechTransferOutPlayerBalance(work);

                            if (chkres == GPTransResult.未完成)
                            {
                                doWallet = Walletlocation.PlayTech;
                                allDone = false;
                            }
                            else
                            {
                                work.GetWalletDone(Walletlocation.PlayTech);
                                userData.PlayTech_Ret = false; //設為已取回
                            }

                            if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] PlayTech取回[{chkres}]");
                        }
                        else
                        {
                            doWallet = Walletlocation.PlayTech;
                            allDone = false;
                        }
                    }

                    if (allDone && work.WallGetList.Contains(Walletlocation.CP))
                    {
                        GPTransResult chkres = DBCache.CPTransferOutPlayerBalance(work);

                        if (chkres == GPTransResult.未完成)
                        {
                            doWallet = Walletlocation.CP;
                            allDone = false;

                            _ = CP.KickMember(userData.UserID);
                        }
                        else
                        {
                            work.GetWalletDone(Walletlocation.CP);
                            userData.CP_Ret = false; //設為已取回
                        }

                        if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] CP取回[{chkres}]");
                    }
                }

                if (allDone)
                {
                    if (PGSDbFg) MyConsole.WriteLine($"X:玩家[{userData.UserID}] 錢包已全部取回, 移除工作");
                    userData.Wallet = Walletlocation.LOCAL;
                    SendUpdateUserBalance(userData);
                    //callback?.Invoke(work.PlayerUid);
                    return errCnt;
                }
                else
                {
                    work.TryTimes++;
                    if (work.TryTimes >= 3)
                    {
                        MyConsole.WriteLine($"X:玩家[{userData.UserID}] {doWallet} 錢包取回失敗, 重試{work.TryTimes}次, 放棄工作");
                        work.AbortWalletGetList(doWallet);
                        work.TryTimes = 0;
                        errCnt++;
                    }
                    else
                    {
                        work.WaitTimes = PGST1Sec * 2; //等待2秒
                        MyConsole.WriteLine($"X:玩家[{userData.UserID}] {doWallet} 錢包取回失敗, 重試{work.TryTimes}次");
                    }
                }

                Thread.Sleep(500); //等待一會再重做一次
            }
        }


        #endregion
    }

    #region H5外部錢包取回
    /// <summary>外部錢包取回結果</summary>
    public enum GPTransResult
    {
        未完成 = 0,
        成功 = 1,
        錢包沒錢轉帳 = 2,
        本地玩家錯誤 = 3,
        遊戲商玩家錯誤 = 4,
        其他錯誤 = 5
    }
    public enum GPTransWork
    {
        取回錢包 = 0,
        踢玩家,
        錢包轉出,
        創帳號
    }

    /// <summary>外部錢包取回工作包</summary>
    public class PGSlotTransTask
    {
        public int Status;
        public int PlayerUid;
        public string LocalTransId;
        public UserData UserData;
        public int Search;
        public int TryTimes;
        public int WaitTimes;

        /// <summary>待取回錢包位置List</summary>
        public List<Walletlocation> WallGetList;
        /// <summary>錢包位置</summary>
        //public Walletlocation Location;
        /// <summary>動作</summary>
        //public GPTransWork Work;


        public PGSlotTransTask(int playerUid, UserData userData)
        {
            this.Status = 0;
            this.PlayerUid = playerUid;
            this.UserData = userData;
            this.LocalTransId = null;
            this.Search = 0;
            this.TryTimes = 0;
            this.WaitTimes = 0;

            WallGetList = userData.GetAllWalletCheckList();
        }

        public void GetWalletDone(Walletlocation wallet)
        {
            WallGetList.Remove(wallet);
            LocalTransId = null;
            TryTimes = 0;
        }

        public void AbortWalletGetList(Walletlocation wallet)
        {
            if (WallGetList.Contains(wallet))
            {
                WallGetList.Remove(wallet);
            }
        }
    }
    #endregion

    public class StreamBox
    {
        public AsyncUserToken Token;
        public byte[] Byte;

        public StreamBox(AsyncUserToken token, byte[] Byte)
        {
            this.Token = token;
            this.Byte = Byte;
        }
    }


